1	use anyhow::Result;
2	use async_trait::async_trait;
3	use op_state::{ApplyResult, Checkpoint, DiffMetadata, PluginCapabilities, StateDiff, StatePlugin};
4	use op_state_store::{FieldSchema, FieldType, PluginSchema};
5	use parking_lot::Mutex;
6	use serde::{Deserialize, Serialize};
7	use simd_json::prelude::*;
8	use simd_json::{json, OwnedValue as Value};
9	use std::collections::{HashMap, HashSet};
10	use std::os::unix::net::UnixListener;
11	use std::path::Path;
12	use std::sync::Arc;
13	use tracing::{info, warn};
14	
15	/// The single active-schema catalog in shared memory. Every plugin reads its
16	/// own slice by name from this one file — there is no per-plugin shm file and
17	/// no diff loop. The schema's declared state IS the desired state.
18	const SHM_SCHEMA_PATH: &str = "/dev/shm/live-schema.json";
19	
20	fn default_protocol() -> String {
21	    "grpc".to_string()
22	}
23	
24	/// A configured unix-domain socket endpoint.
25	///
26	/// In the single-socket model, one shared socket (e.g.
27	/// `/run/ghostbridge/container.sock`) serves all services.  xray routes by
28	/// domain/SNI to the tonic-web gRPC bridge, which listens on this socket and
29	/// demuxes by gRPC service/method (via reflection).
30	#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
31	pub struct SocketEndpoint {
32	    /// Container/service identity (the `createunixsocket --name`). The tonic-web
33	    /// gRPC bridge demuxes by gRPC service/method via server reflection — this
34	    /// name is the routing/identity tag gemma emits into the xray config; it is
35	    /// NOT a network namespace (filesystem UDS are not netns-scoped).
36	    #[serde(default)]
37	    #[schemars(
38	        description = "Container/service identity tag the bridge routes by (createunixsocket --name)",
39	        example = &"netmaker",
40	        extend("x-oscal-subid" = "mut.service.unix-socket.bind-name@v1")
41	    )]
42	    pub name: String,
43	    /// Filesystem path to the shared socket.
44	    #[schemars(
45	        description = "Filesystem path of the shared unix domain socket",
46	        example = &"/run/ghostbridge/container.sock",
47	        extend("x-oscal-subid" = "mut.service.unix-socket.bind-path@v1")
48	    )]
49	    pub path: String,
50	    /// Backend TCP ports this container serves (the `createunixsocket --port`
51	    /// list, e.g. `25,465,587` for mail). Recorded metadata only — tonic-web
52	    /// distinguishes single vs multi protocol and demuxes by reflection, so the
53	    /// plugin neither opens these ports nor maps them; they describe the backend.
54	    #[serde(default)]
55	    #[schemars(
56	        description = "Backend TCP ports the container serves (metadata; tonic-web demuxes by reflection)",
57	        example = &[25u16, 465, 587],
58	        extend("x-oscal-subid" = "mut.service.unix-socket.bind-port@v1")
59	    )]
60	    pub ports: Vec<u16>,
61	    /// Transport protocol carried over the socket.
62	    #[serde(default = "default_protocol")]
63	    #[schemars(
64	        description = "Transport protocol carried over the socket (grpc, jsonrpc, …)",
65	        extend("x-oscal-subid" = "mut.service.unix-socket.bind-protocol@v1")
66	    )]
67	    pub protocol: String,
68	    /// Human-readable label for the shared socket.
