119	pub struct UnixSocketPlugin {
120	    /// Live listeners keyed by socket path. Holding the `UnixListener` keeps the
121	    /// socket bound for the lifetime of the plugin; dropping it tears it down.
122	    active: Arc<Mutex<HashMap<String, UnixListener>>>,
123	}
124	
125	impl UnixSocketPlugin {
126	    pub fn new() -> Self {
127	        Self {
128	            active: Arc::new(Mutex::new(HashMap::new())),
129	        }
130	    }
131	
132	    /// Read this plugin's desired socket set straight from the single active
133	    /// schema catalog in shared memory (zero-copy 1:1). The catalog is keyed by
134	    /// plugin name and each entry carries the schema-declared state.
135	    fn read_desired() -> UnixSocketState {
136	        let Ok(mut bytes) = std::fs::read(SHM_SCHEMA_PATH) else {
137	            return UnixSocketState::default();
138	        };
139	        let Ok(catalog) = simd_json::to_owned_value(&mut bytes) else {
140	            return UnixSocketState::default();
141	        };
142	        let Some(state) = catalog
143	            .get("unix_socket")
144	            .and_then(|versions| versions.as_array())
145	            .and_then(|versions| versions.last())
146	            .and_then(|schema| schema.get("example"))
147	        else {
148	            return UnixSocketState::default();
149	        };
150	        simd_json::serde::from_owned_value::<UnixSocketState>(state.clone()).unwrap_or_default()
151	    }
152	
153	    /// Bind a single endpoint when no shared transport exists. If the shared
154	    /// socket is already present, it is owned by the gRPC bridge and this plugin
155	    /// only registers the endpoint metadata.
156	    fn ensure_bound(
157	        active: &mut HashMap<String, UnixListener>,
158	        endpoint: &SocketEndpoint,
159	    ) -> Result<bool> {
160	        if active.contains_key(&endpoint.path) {
161	            return Ok(false);
162	        }
163	        if let Some(parent) = Path::new(&endpoint.path).parent() {
164	            std::fs::create_dir_all(parent)?;
165	        }
166	        if Path::new(&endpoint.path).exists() {
167	            info!(
168	                socket = %endpoint.path,
169	                name = %endpoint.name,
170	                ports = ?endpoint.ports,
171	                protocol = %endpoint.protocol,
172	                "registered unix socket endpoint on existing shared transport"
173	            );
174	            return Ok(false);
175	        }
176	        let listener = UnixListener::bind(&endpoint.path)?;
177	        listener.set_nonblocking(true)?;
178	        active.insert(endpoint.path.clone(), listener);
179	        info!(
180	            socket = %endpoint.path,
181	            name = %endpoint.name,
182	            ports = ?endpoint.ports,
183	            protocol = %endpoint.protocol,
184	            "bound unix socket endpoint"
185	        );
186	        Ok(true)
187	    }
188	
189	    /// Drop a listener and unlink its socket file. Returns `true` when removed.
190	    fn unbind(active: &mut HashMap<String, UnixListener>, path: &str) -> bool {
191	        if active.remove(path).is_some() {
192	            if let Err(error) = std::fs::remove_file(path) {
193	                warn!(socket = %path, %error, "failed to unlink unix socket file");
194	            }
195	            true
196	        } else {
197	            false
198	        }
199	    }
200	
201	    /// Reconcile the live listeners to exactly the supplied desired set.
202	    fn reconcile(&self, desired: &UnixSocketState) -> ApplyResult {
203	        let mut active = self.active.lock();
204	        let mut changes_applied = Vec::new();
205	        let mut errors = Vec::new();
206	
207	        let wanted: HashSet<String> = desired.sockets.iter().map(|s| s.path.clone()).collect();
208	
209	        for endpoint in &desired.sockets {
210	            match Self::ensure_bound(&mut active, endpoint) {
211	                Ok(true) => changes_applied.push(format!(
212	                    "created socket {} (name {}, ports {:?}, {})",
213	                    endpoint.path, endpoint.name, endpoint.ports, endpoint.protocol
214	                )),
215	                Ok(false) => {}
216	                Err(error) => errors.push(format!(
217	                    "failed to create socket {}: {}",
218	                    endpoint.path, error
219	                )),
220	            }
221	        }
222	
223	        let stale: Vec<String> = active
224	            .keys()
225	            .filter(|path| !wanted.contains(*path))
226	            .cloned()
227	            .collect();
228	        for path in stale {
229	            if Self::unbind(&mut active, &path) {
230	                changes_applied.push(format!("removed socket {}", path));
231	            }
232	        }
233	
234	        ApplyResult {
235	            success: errors.is_empty(),
236	            changes_applied,
237	            errors,
238	            checkpoint: None,
239	        }
240	    }
241	
242	    /// `createunixsocket --name <name> --port <csv>` — register a container/service
243	    /// against the single shared `container.sock`.
244	    ///
245	    /// Pure transport, no OVS: the shared socket is bound once; `name` is the
246	    /// identity/demux tag (gemma emits it into the xray config) and `ports` are
247	    /// recorded backend metadata only. tonic-web distinguishes single vs multi
248	    /// protocol and demuxes by gRPC server reflection, so the plugin neither
249	    /// opens these ports nor maps them — OSCAL rule-enforcement routing lives in
250	    /// the separate OpenFlow/policy layer, not in the socket.
251	    pub fn create_unix_socket(&self, name: impl Into<String>, ports: Vec<u16>) -> ApplyResult {
252	        // Provisioning is pure identity-tag registration: the shared
253	        // `container.sock` is owned by the tonic-web gRPC bridge, not this
254	        // plugin. We never `UnixListener::bind` here — that would race the
255	        // bridge for the socket. The authoritative state update (append/update
256	        // the `SocketEndpoint` keyed by `name`, idempotently) is performed by
257	        // `MutationEngine` when it routes the `createunixsocket` MethodCall.
258	        let name = name.into();
259	        ApplyResult {
260	            success: true,
261	            changes_applied: vec![format!(
262	                "registered '{}' on shared socket {} (ports {:?})",
263	                name, SHARED_CONTAINER_SOCKET, ports
264	            )],
265	            errors: vec![],
266	            checkpoint: None,
267	        }
268	    }
269	}
