1	//! Gemma — the subid → tag → OpenFlow + xray routing brain.
2	//!
3	//! Reads the canonical subid registry from `/etc/ghostbridge/subid-registry.json`
4	//! and writes two tmpfs artifacts:
5	//!   - `/dev/shm/xray-routes.json`    — routes for the op-identity-shuttle
6	//!   - `/dev/shm/openflow-routes.json` — rules for the OpenFlow controller
7	//!
8	//! Per AGENTS.md §4: D-Bus is the control plane; Gemma is a host service that
9	//! produces structured state, not a CLI bypass. It never shells out to network
10	//! tools. OpenFlow rules may be applied via D-Bus by a separate controller.
11	
12	mod ollama;
13	mod ui_gallery;
14	
15	use anyhow::{Context, Result};
16	use serde::{Deserialize, Serialize};
17	use std::collections::HashMap;
18	use std::fs;
19	use std::io::Write;
20	use std::path::Path;
21	use tracing::{info, warn};
22	
23	const SUBID_REGISTRY: &str = "/etc/ghostbridge/subid-registry.json";
24	const XRAY_ROUTES: &str = "/dev/shm/xray-routes.json";
25	const OPENFLOW_ROUTES: &str = "/dev/shm/openflow-routes.json";
26	
27	#[derive(Debug, Clone, Deserialize, Serialize)]
28	struct SubidRegistry {
29	    version: u32,
30	    entries: Vec<RegistryEntry>,
31	}
32	
33	#[derive(Debug, Clone, Deserialize, Serialize)]
34	struct RegistryEntry {
35	    uuid: String,
36	    subid: String,
37	    #[serde(rename = "category")]
38	    category: String,
39	    #[serde(rename = "component_type")]
40	    component_type: String,
41	    subject: String,
42	    verb: String,
43	    version: u8,
44	    tags: Vec<String>,
45	    subdomains: Vec<String>,
46	    #[serde(default, skip_serializing_if = "Option::is_none")]
47	    gemma: Option<GemmaConfig>,
48	}
49	
50	#[derive(Debug, Clone, Deserialize, Serialize)]
51	struct GemmaConfig {
52	    backend: BackendSpec,
53	}
54	
55	#[derive(Debug, Clone, Deserialize, Serialize)]
56	#[serde(tag = "type")]
57	enum BackendSpec {
58	    #[serde(rename = "ingress")]
59	    Ingress,
60	    #[serde(rename = "tcp")]
61	    Tcp { host: String, port: u16 },
62	    #[serde(rename = "grpc")]
63	    Grpc {
64	        host: String,
65	        port: u16,
66	        #[serde(rename = "service_name")]
67	        service_name: String,
68	    },
69	    #[serde(rename = "unix")]
70	    Unix { path: String },
71	    #[serde(rename = "dns")]
72	    Dns { host: String, port: u16 },
73	    /// Internal metadata entry — not xray-routable, produces no outbound.
74	    #[serde(rename = "file")]
75	    File {
76	        #[allow(dead_code)]
77	        path: String,
78	    },
79	    /// Internal service — not xray-routable, produces no outbound.
80	    #[serde(rename = "internal")]
81	    Internal,
82	}
83	
84	#[derive(Debug, Clone, Serialize, Deserialize)]
85	struct XrayRoutingMap {
86	    version: u32,
87	    xray_routes: Vec<XrayRoute>,
88	    openflow_rules: Vec<OpenFlowRule>,
89	}
90	
91	#[derive(Debug, Clone, Serialize, Deserialize)]
92	struct XrayRoute {
93	    tag: String,
94	    subdomains: Vec<String>,
95	    backend: BackendSpec,
96	}
97	
98	#[derive(Debug, Clone, Serialize, Deserialize)]
99	struct OpenFlowRule {
100	    priority: u16,
101	    #[serde(rename = "match_fields")]
102	    match_fields: HashMap<String, String>,
103	    actions: Vec<String>,
104	    description: Option<String>,
105	}
106	
107	fn main() -> Result<()> {
108	    tracing_subscriber::fmt()
109	        .with_env_filter(tracing_subscriber::EnvFilter::from_default_env())
110	        .init();
111	
112	    info!("Gemma routing brain starting");
113	
114	    let registry = load_registry()?;
115	    let routes = derive_routes(&registry);
116	
117	    write_json(XRAY_ROUTES, &routes)?;
118	    write_json(OPENFLOW_ROUTES, &routes)?;
119	
120	    info!(
121	        xray_routes = routes.xray_routes.len(),
122	        openflow_rules = routes.openflow_rules.len(),
123	        "Gemma wrote routing artifacts"
124	    );
125	
126	    // Probe Ollama — the inference backend for gallery prompts. Gemma's
127	    // model comes from Ollama (default: gemma3 via LLM_ENDPOINT/LLM_MODEL_ID),
128	    // not hardcoded strings. When unavailable, the gallery falls back to
129	    // deterministic prompts so the binary still produces output.
130	    let ollama = ollama::OllamaClient::from_env();
131	    match ollama.available_models() {
132	        Some(models) => {
133	            info!(
134	                endpoint = %ollama.endpoint(),
135	                model = %ollama.model(),
136	                available_models = ?models,
137	                "Ollama reachable — gallery prompts will be LLM-generated"
138	            );
139	        }
140	        None => {
141	            warn!(
142	                endpoint = %ollama.endpoint(),
143	                model = %ollama.model(),
144	                "Ollama unreachable — gallery will use deterministic fallback prompts"
145	            );
146	        }
147	    }
148	
149	    // Generate the json-render.dev UI spec gallery (200 unique specs).
150	    // Prompts are LLM-generated via Ollama when available.
151	    if let Err(e) = ui_gallery::generate_gallery(&ollama) {
152	        warn!("Gemma UI gallery generation failed: {e}");
153	    }
154	
155	    Ok(())
156	}
157	
158	fn load_registry() -> Result<SubidRegistry> {
159	    let raw = fs::read_to_string(SUBID_REGISTRY)
160	        .with_context(|| format!("failed to read subid registry: {SUBID_REGISTRY}"))?;
161	    let parsed: SubidRegistry =
162	        serde_json::from_str(&raw).with_context(|| "failed to parse subid registry as JSON")?;
163	    Ok(parsed)
164	}
165	
166	fn derive_routes(registry: &SubidRegistry) -> XrayRoutingMap {
167	    let mut xray_routes = Vec::new();
168	    let mut openflow_rules = default_privacy_chain();
169	    let mut claimed_subdomains: std::collections::HashSet<String> =
170	        std::collections::HashSet::new();
171	
172	    for entry in &registry.entries {
173	        let Some(gemma) = &entry.gemma else { continue };
174	
175	        // Skip non-routable backends — they are metadata (schema files,
176	        // internal services) that should not produce xray outbounds.
177	        if matches!(
178	            gemma.backend,
179	            BackendSpec::File { .. } | BackendSpec::Internal
180	        ) {
181	            continue;
182	        }
183	
184	        let tag = entry
185	            .tags
186	            .first()
187	            .cloned()
188	            .unwrap_or_else(|| entry.subject.clone());
189	
190	        // Skip duplicate tags — first declaration wins.
191	        if xray_routes.iter().any(|r: &XrayRoute| r.tag == tag) {
192	            continue;
193	        }
194	
195	        // Filter out subdomains already claimed by an earlier route.
196	        // xray uses first-match routing, so a duplicate subdomain on a later
197	        // route is silently unreachable. Warn so the operator can fix the
198	        // registry conflict instead of debugging dead routes.
199	        let subdomains: Vec<String> = entry
200	            .subdomains
201	            .iter()
202	            .filter(|sd| {
203	                if claimed_subdomains.contains(*sd) {
204	                    warn!(
205	                        subdomain = %sd,
206	                        conflicting_tag = %tag,
207	                        "Subdomain already claimed by an earlier route; \
208	                         skipping this route's claim (xray first-match wins)"
209	                    );
210	                    false
211	                } else {
212	                    true
213	                }
214	            })
215	            .cloned()
216	            .collect();
217	
218	        // If every subdomain was already claimed, this route has nothing
219	        // routable left — skip it entirely.
220	        if !entry.subdomains.is_empty() && subdomains.is_empty() {
221	            warn!(
222	                tag = %tag,
223	                subid = %entry.subid,
224	                "All subdomains for this route were already claimed; skipping route"
225	            );
226	            continue;
227	        }
228	
229	        for sd in &subdomains {
230	            claimed_subdomains.insert(sd.clone());
231	        }
232	
233	        let route = XrayRoute {
234	            tag: tag.clone(),
235	            subdomains,
236	            backend: gemma.backend.clone(),
237	        };
238	        xray_routes.push(route);
239	
240	        if let Some(rule) = backend_to_openflow_rule(&tag, &gemma.backend) {
241	            openflow_rules.push(rule);
242	        }
243	    }
244	
245	    XrayRoutingMap {
246	        version: 1,
247	        xray_routes,
248	        openflow_rules,
249	    }
250	}
251	
252	/// Default privacy chain flows for the GhostBridge OVS bridge.
253	/// These match the conventions in `crates/op-plugins/src/state_plugins/privacy_router.rs`.
254	fn default_privacy_chain() -> Vec<OpenFlowRule> {
255	    vec![
256	        OpenFlowRule {
257	            priority: 100,
258	            match_fields: HashMap::from([("in_port".to_string(), "gbr_wg".to_string())]),
259	            actions: vec!["output:gbr_warp".to_string()],
260	            description: Some("gbr_wg -> gbr_warp".to_string()),
261	        },
262	        OpenFlowRule {
263	            priority: 100,
264	            match_fields: HashMap::from([("in_port".to_string(), "gbr_warp".to_string())]),
265	            actions: vec!["output:gbr_xray".to_string()],
266	            description: Some("gbr_warp -> gbr_xray".to_string()),
267	        },
268	        OpenFlowRule {
269	            priority: 100,
270	            match_fields: HashMap::from([("in_port".to_string(), "gbr_xray".to_string())]),
271	            actions: vec!["output:gbr_warp".to_string()],
272	            description: Some("gbr_xray -> gbr_warp".to_string()),
273	        },
274	        OpenFlowRule {
275	            priority: 200,
276	            match_fields: HashMap::from([("dl_type".to_string(), "0x0806".to_string())]),
277	            actions: vec!["arp_responder".to_string()],
278	            description: Some("ARP Responder for privacy network".to_string()),
279	        },
280	    ]
281	}
282	
283	/// Translate a Gemma backend into an OpenFlow rule for the bridge.
284	/// Only TCP/GRPC backends produce IP/Port matchable rules here; Unix sockets
285	/// route through the tonic-web gRPC bridge (reflection demuxes) so no OVS
286	/// bridge match is needed.
287	fn backend_to_openflow_rule(tag: &str, backend: &BackendSpec) -> Option<OpenFlowRule> {
288	    let (host, port) = match backend {
289	        BackendSpec::Tcp { host, port } => (host.clone(), *port),
290	        BackendSpec::Grpc { host, port, .. } => (host.clone(), *port),
291	        BackendSpec::Ingress
292	        | BackendSpec::Unix { .. }
293	        | BackendSpec::Dns { .. }
294	        | BackendSpec::File { .. }
295	        | BackendSpec::Internal => return None,
296	    };
297	
298	    let mut match_fields = HashMap::new();
299	    match_fields.insert("dl_type".to_string(), "0x0800".to_string());
300	    match_fields.insert("nw_proto".to_string(), "6".to_string()); // TCP
301	    match_fields.insert("nw_dst".to_string(), host.clone());
302	    match_fields.insert("tp_dst".to_string(), port.to_string());
303	
304	    Some(OpenFlowRule {
305	        priority: 150,
306	        match_fields,
307	        actions: vec!["output:ovsbr0-mgmt".to_string()],
308	        description: Some(format!("Gemma: {tag} -> host backend {host}:{port}")),
309	    })
310	}
311	
312	fn write_json<P: AsRef<Path>>(path: P, value: &XrayRoutingMap) -> Result<()> {
313	    let tmp = format!("{}.tmp", path.as_ref().display());
314	    let mut f =
315	        fs::File::create(&tmp).with_context(|| format!("failed to create tmp file: {tmp}"))?;
316	    let json =
317	        serde_json::to_string_pretty(value).with_context(|| "failed to serialize routing map")?;
318	    f.write_all(json.as_bytes())
319	        .with_context(|| format!("failed to write tmp file: {tmp}"))?;
320	    f.sync_data()
321	        .with_context(|| format!("failed to sync tmp file: {tmp}"))?;
322	    fs::rename(&tmp, path.as_ref())
323	        .with_context(|| format!("failed to rename {tmp} to {}", path.as_ref().display()))?;
324	    Ok(())
325	}
326	
327	#[cfg(test)]
328	mod tests {
329	    use super::*;
330	
331	    fn registry_entry(
332	        subid: &str,
333	        subject: &str,
334	        tag: &str,
335	        subdomains: Vec<&str>,
336	        backend: BackendSpec,
337	    ) -> RegistryEntry {
338	        RegistryEntry {
339	            uuid: format!("uuid-{subid}"),
