348	            gemma: Some(GemmaConfig { backend }),
349	        }
350	    }
351	
352	    #[test]
353	    fn should_dedupe_duplicate_subdomains_first_route_wins() {
354	        let registry = SubidRegistry {
355	            version: 1,
356	            entries: vec![
357	                registry_entry(
358	                    "exp.service.zeroclaw-serve@v1",
359	                    "zeroclaw",
360	                    "grpc-bridge",
361	                    vec!["assistant.ghostbridge.tech"],
362	                    BackendSpec::Grpc {
363	                        host: "127.0.0.1".into(),
364	                        port: 18789,
365	                        service_name: "Ghostbridge.StateSync".into(),
366	                    },
367	                ),
368	                registry_entry(
369	                    "exp.service.zeroclaw-schema.grpc-web@v1",
