//! Gemma — the subid → tag → OpenFlow + xray routing brain.
//!
//! Reads the canonical subid registry from `/etc/ghostbridge/subid-registry.json`
//! and writes two tmpfs artifacts:
//!   - `/dev/shm/xray-routes.json`    — routes for the op-identity-shuttle
//!   - `/dev/shm/openflow-routes.json` — rules for the OpenFlow controller
//!
//! Per AGENTS.md §4: D-Bus is the control plane; Gemma is a host service that
//! produces structured state, not a CLI bypass. It never shells out to network
//! tools. OpenFlow rules may be applied via D-Bus by a separate controller.

mod ollama;
mod ui_gallery;

use anyhow::{Context, Result};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::fs;
use std::io::Write;
use std::path::Path;
use tracing::{info, warn};

const SUBID_REGISTRY: &str = "/etc/ghostbridge/subid-registry.json";
const XRAY_ROUTES: &str = "/dev/shm/xray-routes.json";
const OPENFLOW_ROUTES: &str = "/dev/shm/openflow-routes.json";

#[derive(Debug, Clone, Deserialize, Serialize)]
struct SubidRegistry {
    version: u32,
    entries: Vec<RegistryEntry>,
}

#[derive(Debug, Clone, Deserialize, Serialize)]
struct RegistryEntry {
    uuid: String,
    subid: String,
    #[serde(rename = "category")]
    category: String,
    #[serde(rename = "component_type")]
    component_type: String,
    subject: String,
    verb: String,
    version: u8,
    tags: Vec<String>,
    subdomains: Vec<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    gemma: Option<GemmaConfig>,
}

#[derive(Debug, Clone, Deserialize, Serialize)]
struct GemmaConfig {
    backend: BackendSpec,
}

#[derive(Debug, Clone, Deserialize, Serialize)]
#[serde(tag = "type")]
enum BackendSpec {
    #[serde(rename = "ingress")]
    Ingress,
    #[serde(rename = "tcp")]
    Tcp { host: String, port: u16 },
    #[serde(rename = "grpc")]
    Grpc {
        host: String,
        port: u16,
        #[serde(rename = "service_name")]
        service_name: String,
    },
    #[serde(rename = "unix")]
    Unix { path: String },
    #[serde(rename = "dns")]
    Dns { host: String, port: u16 },
    /// Internal metadata entry — not xray-routable, produces no outbound.
    #[serde(rename = "file")]
    File {
        #[allow(dead_code)]
        path: String,
    },
    /// Internal service — not xray-routable, produces no outbound.
    #[serde(rename = "internal")]
    Internal,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct XrayRoutingMap {
    version: u32,
    xray_routes: Vec<XrayRoute>,
    openflow_rules: Vec<OpenFlowRule>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct XrayRoute {
    tag: String,
    subdomains: Vec<String>,
    backend: BackendSpec,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct OpenFlowRule {
    priority: u16,
    #[serde(rename = "match_fields")]
    match_fields: HashMap<String, String>,
    actions: Vec<String>,
    description: Option<String>,
}

fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(tracing_subscriber::EnvFilter::from_default_env())
        .init();

    info!("Gemma routing brain starting");

    let registry = load_registry()?;
    let routes = derive_routes(&registry);

    write_json(XRAY_ROUTES, &routes)?;
    write_json(OPENFLOW_ROUTES, &routes)?;

    info!(
        xray_routes = routes.xray_routes.len(),
        openflow_rules = routes.openflow_rules.len(),
        "Gemma wrote routing artifacts"
    );

    // Probe Ollama — the inference backend for gallery prompts. Gemma's
    // model comes from Ollama (default: gemma3 via LLM_ENDPOINT/LLM_MODEL_ID),
    // not hardcoded strings. When unavailable, the gallery falls back to
    // deterministic prompts so the binary still produces output.
    let ollama = ollama::OllamaClient::from_env();
    match ollama.available_models() {
        Some(models) => {
            info!(
                endpoint = %ollama.endpoint(),
                model = %ollama.model(),
                available_models = ?models,
                "Ollama reachable — gallery prompts will be LLM-generated"
            );
        }
        None => {
            warn!(
                endpoint = %ollama.endpoint(),
                model = %ollama.model(),
                "Ollama unreachable — gallery will use deterministic fallback prompts"
            );
        }
    }

    // Generate the json-render.dev UI spec gallery (200 unique specs).
    // Prompts are LLM-generated via Ollama when available.
    if let Err(e) = ui_gallery::generate_gallery(&ollama) {
        warn!("Gemma UI gallery generation failed: {e}");
    }

    Ok(())
}

fn load_registry() -> Result<SubidRegistry> {
    let raw = fs::read_to_string(SUBID_REGISTRY)
        .with_context(|| format!("failed to read subid registry: {SUBID_REGISTRY}"))?;
    let parsed: SubidRegistry =
        serde_json::from_str(&raw).with_context(|| "failed to parse subid registry as JSON")?;
    Ok(parsed)
}

fn derive_routes(registry: &SubidRegistry) -> XrayRoutingMap {
    let mut xray_routes = Vec::new();
    let mut openflow_rules = default_privacy_chain();
    let mut claimed_subdomains: std::collections::HashSet<String> =
        std::collections::HashSet::new();

    for entry in &registry.entries {
        let Some(gemma) = &entry.gemma else { continue };

        // Skip non-routable backends — they are metadata (schema files,
        // internal services) that should not produce xray outbounds.
        if matches!(
            gemma.backend,
            BackendSpec::File { .. } | BackendSpec::Internal
        ) {
            continue;
        }

        let tag = entry
            .tags
            .first()
            .cloned()
            .unwrap_or_else(|| entry.subject.clone());

        // Skip duplicate tags — first declaration wins.
        if xray_routes.iter().any(|r: &XrayRoute| r.tag == tag) {
            continue;
        }

        // Filter out subdomains already claimed by an earlier route.
        // xray uses first-match routing, so a duplicate subdomain on a later
        // route is silently unreachable. Warn so the operator can fix the
        // registry conflict instead of debugging dead routes.
        let subdomains: Vec<String> = entry
            .subdomains
            .iter()
            .filter(|sd| {
                if claimed_subdomains.contains(*sd) {
                    warn!(
                        subdomain = %sd,
                        conflicting_tag = %tag,
                        "Subdomain already claimed by an earlier route; \
                         skipping this route's claim (xray first-match wins)"
                    );
                    false
                } else {
                    true
                }
            })
            .cloned()
            .collect();

        // If every subdomain was already claimed, this route has nothing
        // routable left — skip it entirely.
        if !entry.subdomains.is_empty() && subdomains.is_empty() {
            warn!(
                tag = %tag,
                subid = %entry.subid,
                "All subdomains for this route were already claimed; skipping route"
            );
            continue;
        }

        for sd in &subdomains {
            claimed_subdomains.insert(sd.clone());
        }

        let route = XrayRoute {
            tag: tag.clone(),
            subdomains,
            backend: gemma.backend.clone(),
        };
        xray_routes.push(route);

        if let Some(rule) = backend_to_openflow_rule(&tag, &gemma.backend) {
            openflow_rules.push(rule);
        }
    }

    XrayRoutingMap {
        version: 1,
        xray_routes,
        openflow_rules,
    }
}

/// Default privacy chain flows for the GhostBridge OVS bridge.
/// These match the conventions in `crates/op-plugins/src/state_plugins/privacy_router.rs`.
fn default_privacy_chain() -> Vec<OpenFlowRule> {
    vec![
        OpenFlowRule {
            priority: 100,
            match_fields: HashMap::from([("in_port".to_string(), "gbr_wg".to_string())]),
            actions: vec!["output:gbr_warp".to_string()],
            description: Some("gbr_wg -> gbr_warp".to_string()),
        },
        OpenFlowRule {
            priority: 100,
            match_fields: HashMap::from([("in_port".to_string(), "gbr_warp".to_string())]),
            actions: vec!["output:gbr_xray".to_string()],
            description: Some("gbr_warp -> gbr_xray".to_string()),
        },
        OpenFlowRule {
            priority: 100,
            match_fields: HashMap::from([("in_port".to_string(), "gbr_xray".to_string())]),
            actions: vec!["output:gbr_warp".to_string()],
            description: Some("gbr_xray -> gbr_warp".to_string()),
        },
        OpenFlowRule {
            priority: 200,
            match_fields: HashMap::from([("dl_type".to_string(), "0x0806".to_string())]),
            actions: vec!["arp_responder".to_string()],
            description: Some("ARP Responder for privacy network".to_string()),
        },
    ]
}

/// Translate a Gemma backend into an OpenFlow rule for the bridge.
/// Only TCP/GRPC backends produce IP/Port matchable rules here; Unix sockets
/// route through the tonic-web gRPC bridge (reflection demuxes) so no OVS
/// bridge match is needed.
fn backend_to_openflow_rule(tag: &str, backend: &BackendSpec) -> Option<OpenFlowRule> {
    let (host, port) = match backend {
        BackendSpec::Tcp { host, port } => (host.clone(), *port),
        BackendSpec::Grpc { host, port, .. } => (host.clone(), *port),
        BackendSpec::Ingress
        | BackendSpec::Unix { .. }
        | BackendSpec::Dns { .. }
        | BackendSpec::File { .. }
        | BackendSpec::Internal => return None,
    };

    let mut match_fields = HashMap::new();
    match_fields.insert("dl_type".to_string(), "0x0800".to_string());
    match_fields.insert("nw_proto".to_string(), "6".to_string()); // TCP
    match_fields.insert("nw_dst".to_string(), host.clone());
    match_fields.insert("tp_dst".to_string(), port.to_string());

    Some(OpenFlowRule {
        priority: 150,
        match_fields,
        actions: vec!["output:ovsbr0-mgmt".to_string()],
        description: Some(format!("Gemma: {tag} -> host backend {host}:{port}")),
    })
}

fn write_json<P: AsRef<Path>>(path: P, value: &XrayRoutingMap) -> Result<()> {
    let tmp = format!("{}.tmp", path.as_ref().display());
    let mut f =
        fs::File::create(&tmp).with_context(|| format!("failed to create tmp file: {tmp}"))?;
    let json =
        serde_json::to_string_pretty(value).with_context(|| "failed to serialize routing map")?;
    f.write_all(json.as_bytes())
        .with_context(|| format!("failed to write tmp file: {tmp}"))?;
    f.sync_data()
        .with_context(|| format!("failed to sync tmp file: {tmp}"))?;
    fs::rename(&tmp, path.as_ref())
        .with_context(|| format!("failed to rename {tmp} to {}", path.as_ref().display()))?;
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    fn registry_entry(
        subid: &str,
        subject: &str,
        tag: &str,
        subdomains: Vec<&str>,
        backend: BackendSpec,
    ) -> RegistryEntry {
        RegistryEntry {
            uuid: format!("uuid-{subid}"),
            subid: subid.to_string(),
            category: "exp".to_string(),
            component_type: "service".to_string(),
            subject: subject.to_string(),
            verb: "serve".to_string(),
            version: 1,
            tags: vec![tag.to_string()],
            subdomains: subdomains.into_iter().map(String::from).collect(),
            gemma: Some(GemmaConfig { backend }),
        }
    }

    #[test]
    fn should_dedupe_duplicate_subdomains_first_route_wins() {
        let registry = SubidRegistry {
            version: 1,
            entries: vec![
                registry_entry(
                    "exp.service.zeroclaw-serve@v1",
                    "zeroclaw",
                    "grpc-bridge",
                    vec!["assistant.ghostbridge.tech"],
                    BackendSpec::Grpc {
                        host: "127.0.0.1".into(),
                        port: 18789,
                        service_name: "Ghostbridge.StateSync".into(),
                    },
                ),
                registry_entry(
                    "exp.service.zeroclaw-schema.grpc-web@v1",
                    "zeroclaw-schema",
                    "zeroclaw-schema",
                    vec!["assistant.ghostbridge.tech"],
                    BackendSpec::Grpc {
                        host: "0.0.0.0".into(),
                        port: 8090,
                        service_name: "zeroclaw.ZeroclawService".into(),
                    },
                ),
            ],
        };

        let routes = derive_routes(&registry);

        // First route keeps the subdomain; second route is skipped entirely
        // because its only subdomain was already claimed (xray first-match).
        let grpc_bridge = routes
            .xray_routes
            .iter()
            .find(|r| r.tag == "grpc-bridge")
            .expect("grpc-bridge route exists");
        assert!(grpc_bridge
            .subdomains
            .contains(&"assistant.ghostbridge.tech".to_string()));

        assert!(
            !routes
                .xray_routes
                .iter()
                .any(|r| r.tag == "zeroclaw-schema"),
            "zeroclaw-schema route should be skipped — its subdomain was already claimed"
        );
    }

    #[test]
    fn should_skip_route_when_all_subdomains_claimed() {
        let registry = SubidRegistry {
            version: 1,
            entries: vec![
                registry_entry(
                    "exp.service.first@v1",
                    "first",
                    "first",
                    vec!["only.ghostbridge.tech"],
                    BackendSpec::Tcp {
                        host: "127.0.0.1".into(),
                        port: 8000,
                    },
                ),
                registry_entry(
                    "exp.service.second@v1",
                    "second",
                    "second",
                    vec!["only.ghostbridge.tech"],
                    BackendSpec::Tcp {
                        host: "127.0.0.1".into(),
                        port: 9000,
                    },
                ),
            ],
        };

        let routes = derive_routes(&registry);

        // First route keeps the subdomain; second route is skipped entirely.
        assert_eq!(routes.xray_routes.len(), 1);
        assert_eq!(routes.xray_routes[0].tag, "first");
    }

    #[test]
    fn should_preserve_unique_subdomains_across_routes() {
        let registry = SubidRegistry {
            version: 1,
            entries: vec![
                registry_entry(
                    "exp.service.cognitive-mcp@v1",
                    "cognitive-mcp",
                    "cognitive-mcp",
                    vec!["mcp.internal"],
                    BackendSpec::Grpc {
                        host: "127.0.0.1".into(),
                        port: 3003,
                        service_name: "operation.cognitive.v1.CognitiveToolService".into(),
                    },
                ),
                registry_entry(
                    "src.service.qdrant@v1",
                    "qdrant",
                    "qdrant",
                    vec!["qdrant.ghostbridge.tech"],
                    BackendSpec::Unix {
                        path: "/run/qdrant.sock".into(),
                    },
                ),
            ],
        };

        let routes = derive_routes(&registry);
        assert_eq!(routes.xray_routes.len(), 2);
    }
}

