1	//! D-Bus object server for projections.
2	//!
3	//! Serves every Projection through org.opdbus.v1.plugins at
4	//! /org/opdbus/v1/plugins/<plugin>. Nothing mounts outside the plugins root:
5	//! no plugin means no schema means no object.
6	//!
7	//! Data is read 1:1 from the shared-memory projection layer
8	//! (`/dev/shm/opdbus/projections/<plugin>.json`) on every property access.
9	//! No held cache — the projected tree is a pure read-through of the mutation
10	//! fold written by the MutationEngine (the single write door).
11	//!
12	//! Tree structure is derived on-demand: the `ProjectionRoot` interface at
13	//! `/org/opdbus/v1/plugins` exposes a `refresh()` D-Bus method that re-reads
14	//! shm and mounts/unmounts objects to match. No gRPC subscription, no polling,
15	//! no inotify — the tree syncs when asked.
16	
17	use anyhow::Result;
18	use std::collections::HashSet;
19	use std::sync::Arc;
20	use tokio::sync::Mutex;
21	use tracing::{debug, info};
22	use zbus::{connection::Builder, interface, object_server::SignalEmitter, Connection};
23	
24	/// A single projected object on the D-Bus object server.
25	///
26	/// Reads its data 1:1 from the shm projection layer on every property access.
27	/// No held cache — the mutation fold in `/dev/shm/opdbus/projections/` is the
28	/// single source of truth, written by the MutationEngine on every mutation.
29	pub struct ProjectedObject {
30	    /// The plugin that owns this object (e.g. "wireguard").
31	    pub plugin_id: String,
32	    /// Path segments below the plugin root (empty for the plugin root itself).
33	    /// e.g. `["interfaces", "0", "peers"]` for
34	    /// `/org/opdbus/v1/plugins/wireguard/interfaces/0/peers`
35	    pub path_segments: Vec<String>,
36	}
37	
38	#[interface(name = "org.opdbus.v1.plugins.ProjectedObject")]
39	impl ProjectedObject {
40	    /// The schema/entity type for this object (plugin id for roots, "plugin.object" for nested)
41	    #[zbus(property)]
42	    async fn entity_type(&self) -> String {
43	        if self.path_segments.is_empty() {
44	            self.plugin_id.clone()
45	        } else {
46	            "plugin.object".to_string()
47	        }
48	    }
49	
50	    /// The unique entity ID within its type
51	    #[zbus(property)]
52	    async fn entity_id(&self) -> String {
53	        if self.path_segments.is_empty() {
54	            self.plugin_id.clone()
55	        } else {
56	            format!("{}:/{}", self.plugin_id, self.path_segments.join("/"))
57	        }
58	    }
59	
60	    /// Current projection state: always Valid (1:1 read of canonical state).
61	    #[zbus(property)]
62	    async fn state(&self) -> String {
63	        "Valid".to_string()
64	    }
65	
66	    /// Full projection data as a JSON string, read 1:1 from shm.
67	    #[zbus(property)]
68	    async fn data(&self) -> String {
69	        read_projected_data(&self.plugin_id, &self.path_segments)
70	    }
71	
72	    /// Signal emitted when this object's data changes
73	    #[zbus(signal)]
74	    async fn updated(emitter: &SignalEmitter<'_>, data_json: &str) -> zbus::Result<()>;
75	}
76	
77	/// Read projected data for a plugin/path from the shm layer (1:1, zero held cache).
78	///
79	/// For the plugin root (empty `path_segments`), returns the `data` field from
80	/// the composite shm object (or the raw file if not a composite).
81	/// For nested objects, parses the JSON, navigates to the path within `data`,
82	/// and re-serializes.
83	fn read_projected_data(plugin_id: &str, path_segments: &[String]) -> String {
84	    let bytes = match op_core::projection_shm::read_projection_bytes(plugin_id) {
85	        Some(b) => b,
86	        None => return "{}".to_string(),
87	    };
88	    let value: serde_json::Value = match serde_json::from_slice(&bytes) {
89	        Ok(v) => v,
90	        Err(_) => return "{}".to_string(),
91	    };
92	
93	    // Navigate from the `data` field if present (composite shm format).
94	    let root = value.get("data").unwrap_or(&value);
95	
96	    if path_segments.is_empty() {
97	        serde_json::to_string(root).unwrap_or_else(|_| "{}".to_string())
98	    } else {
99	        match navigate_json(root, path_segments) {
100	            Some(v) => serde_json::to_string(v).unwrap_or_else(|_| "{}".to_string()),
101	            None => "{}".to_string(),
102	        }
103	    }
104	}
105	
106	/// Navigate a JSON value by path segments (object keys or array indices).
107	fn navigate_json<'a>(
108	    value: &'a serde_json::Value,
109	    segments: &[String],
110	) -> Option<&'a serde_json::Value> {
111	    let mut current = value;
112	    for segment in segments {
113	        current = if let Ok(idx) = segment.parse::<usize>() {
114	            current.get(idx)?
115	        } else {
116	            current.get(segment.as_str())?
117	        };
118	    }
119	    Some(current)
120	}
121	
122	/// Derives the D-Bus object path from a projection's entity_type and entity_id.
123	///
124	/// Every projected object lives under the single plugins root, and nested
125	/// objects live under the plugin that produced them. No plugin means no schema
126	/// means no object — nothing is ever mounted outside this path.
127	///
128	/// entity_type "mail_server", entity_id "mail_server"
129	///   → /org/opdbus/v1/plugins/mail_server
130	/// entity_type "plugin.object", entity_id "wireguard:/interfaces/0"
131	///   → /org/opdbus/v1/plugins/wireguard/interfaces/0
132	pub fn projection_path(entity_type: &str, entity_id: &str) -> String {
133	    if entity_type == "plugin.object" {
134	        if let Some((plugin_id, object_path)) = entity_id.split_once(':') {
135	            return plugin_object_path(plugin_id, object_path);
136	        }
137	    }
138	
139	    op_plugins::canonical::plugin_path(if entity_id.is_empty() {
140	        entity_type
141	    } else {
142	        entity_id
143	    })
144	}
145	
146	fn plugin_object_path(plugin_id: &str, object_path: &str) -> String {
147	    let mut path = op_plugins::canonical::plugin_path(plugin_id);
148	
149	    for segment in object_path.split('/').filter(|segment| !segment.is_empty()) {
150	        path.push('/');
151	        path.push_str(&sanitize_path_segment(segment));
152	    }
153	
154	    path
155	}
156	
157	fn sanitize_path_segment(segment: &str) -> String {
158	    let sanitized: String = segment
159	        .chars()
160	        .filter_map(|c| {
161	            if c.is_ascii_alphanumeric() || c == '_' {
162	                Some(c)
163	            } else if c == '-' || c == '.' {
164	                Some('_')
165	            } else {
166	                None
167	            }
168	        })
169	        .take(255)
170	        .collect();
171	
172	    if sanitized.is_empty() {
173	        "_".to_string()
174	    } else {
175	        sanitized
176	    }
177	}
178	
179	/// Build the D-Bus object path from a plugin id and path segments.
180	fn build_projected_path(plugin_id: &str, path_segments: &[String]) -> String {
181	    let mut path = format!(
182	        "{}/{}",
183	        op_plugins::canonical::PLUGIN_BASE_PATH,
184	        sanitize_path_segment(plugin_id)
185	    );
186	    for seg in path_segments {
187	        path.push('/');
188	        path.push_str(&sanitize_path_segment(seg));
189	    }
190	    path
191	}
192	
193	/// Root interface at `/org/opdbus/v1/plugins`.
194	///
195	/// Always present so D-Bus introspection works even with zero plugins mounted.
196	/// The `plugins` property reads shm live. The `refresh()` method re-reads shm
197	/// and syncs the D-Bus tree (mount/unmount objects to match). This is the
198	/// dynamic-mount mechanism: no gRPC, no polling, no inotify — the tree is
199	/// derived on demand.
200	pub struct ProjectionRoot {
201	    objects: Arc<Mutex<HashSet<String>>>,
202	}
203	
204	#[interface(name = "org.opdbus.v1.plugins.ProjectionRoot")]
205	impl ProjectionRoot {
206	    /// List of plugin IDs currently projected in shm (live read).
207	    #[zbus(property)]
208	    async fn plugins(&self) -> Vec<String> {
209	        op_core::projection_shm::list_projected_plugins()
210	    }
211	
212	    /// Number of D-Bus objects currently mounted.
213	    #[zbus(property)]
214	    async fn object_count(&self) -> u64 {
215	        self.objects.lock().await.len() as u64
216	    }
217	
218	    /// Re-read shm and sync the D-Bus tree. Mounts new objects, unmounts stale
219	    /// ones. Returns the total object count after refresh.
220	    ///
221	    /// Call this after a mutation has written new state to shm. The
222	    /// MutationEngine can call this via D-Bus after writing to shm, or any
223	    /// client can call it to force a tree refresh.
224	    async fn refresh(&self, #[zbus(connection)] conn: &Connection) -> u64 {
225	        let mut objects = self.objects.lock().await;
226	        match sync_all_from_shm(conn, &mut objects).await {
227	            Ok(()) => objects.len() as u64,
228	            Err(e) => {
229	                tracing::warn!(error = %e, "refresh() failed");
230	                objects.len() as u64
231	            }
232	        }
233	    }
234	}
235	
236	/// Read all plugins from shm, derive paths, and sync the D-Bus tree.
237	///
238	/// For each plugin in shm, derives all nested object paths from the JSON
239	/// structure and mounts/unmounts `ProjectedObject` instances to match.
240	/// Plugins that are in shm but not yet mounted are added; objects that are
241	/// mounted but no longer in shm are removed.
242	async fn sync_all_from_shm(
243	    conn: &Connection,
244	    objects: &mut HashSet<String>,
245	) -> Result<()> {
246	    let plugins = op_core::projection_shm::list_projected_plugins();
247	
248	    // Unmount plugins that are no longer in shm.
249	    let plugin_root_base = op_plugins::canonical::plugin_path("");
250	    let _ = plugin_root_base; // path prefix helper
251	
252	    let to_remove: Vec<String> = objects
253	        .iter()
254	        .filter(|p| {
255	            // Keep only paths whose plugin is still in shm
256	            let parts: Vec<&str> = p.trim_start_matches('/').split('/').collect();
257	            if parts.len() >= 5 && parts[0] == "org" && parts[1] == "opdbus" && parts[2] == "v1" && parts[3] == "plugins" {
258	                let plugin_id = parts[4];
259	                !plugins.iter().any(|p| p.as_str() == plugin_id)
260	            } else {
261	                false
262	            }
263	        })
264	        .cloned()
265	        .collect();
266	
267	    for path in to_remove {
268	        if objects.remove(&path) {
269	            conn.object_server()
270	                .remove::<ProjectedObject, _>(path.as_str())
271	                .await?;
272	            debug!(path, "Unmounted stale D-Bus projection object (plugin gone from shm)");
273	        }
274	    }
275	
276	    // Mount/sync all plugins currently in shm.
277	    for plugin_id in &plugins {
278	        if let Some(paths) = read_and_derive_paths(plugin_id) {
279	            sync_plugin_paths(conn, objects, plugin_id, &paths).await?;
280	        }
281	    }
282	
283	    Ok(())
284	}
285	
286	/// Sync a single plugin's D-Bus objects to match the derived paths.
287	async fn sync_plugin_paths(
288	    conn: &Connection,
289	    objects: &mut HashSet<String>,
290	    plugin_id: &str,
291	    paths: &[Vec<String>],
292	) -> Result<()> {
293	    let new_paths: HashSet<String> = paths
294	        .iter()
295	        .map(|segs| build_projected_path(plugin_id, segs))
296	        .collect();
297	
298	    let plugin_root = op_plugins::canonical::plugin_path(plugin_id);
299	    let plugin_prefix = format!("{}/", plugin_root);
300	
301	    // Unmount paths that no longer exist in the derived set.
302	    let to_remove: Vec<String> = objects
303	        .iter()
304	        .filter(|p| {
305	            (**p == plugin_root || p.starts_with(&plugin_prefix))
306	                && !new_paths.contains(*p)
307	        })
308	        .cloned()
309	        .collect();
310	
311	    for path in to_remove {
312	        if objects.remove(&path) {
313	            conn.object_server()
314	                .remove::<ProjectedObject, _>(path.as_str())
315	                .await?;
316	            debug!(path, "Unmounted stale D-Bus projection object");
317	        }
318	    }
319	
320	    // Mount all current paths.
321	    for segs in paths {
322	        let path = build_projected_path(plugin_id, segs);
323	        if !objects.contains(&path) {
324	            let obj = ProjectedObject {
325	                plugin_id: plugin_id.to_string(),
326	                path_segments: segs.to_vec(),
327	            };
328	            conn.object_server().at(path.as_str(), obj).await?;
329	            objects.insert(path.clone());
330	            debug!(path, "Mounted D-Bus projection object");
331	        }
332	    }
333	
334	    Ok(())
335	}
336	
337	/// Read a plugin's projection from shm and derive all D-Bus object paths.
338	fn read_and_derive_paths(plugin_id: &str) -> Option<Vec<Vec<String>>> {
339	    let bytes = op_core::projection_shm::read_projection_bytes(plugin_id)?;
340	    let value: serde_json::Value = serde_json::from_slice(&bytes).ok()?;
341	    // Derive paths from the `data` field if present (composite shm format).
342	    let root = value.get("data").unwrap_or(&value);
343	    Some(derive_paths_from_state(root))
344	}
345	
346	/// Derive all D-Bus object paths from a plugin's state JSON.
347	fn derive_paths_from_state(value: &serde_json::Value) -> Vec<Vec<String>> {
348	    let mut paths = vec![Vec::new()]; // root (plugin root)
349	    derive_paths_recursive(value, &mut Vec::new(), &mut paths);
350	    paths
351	}
352	
353	fn derive_paths_recursive(
354	    value: &serde_json::Value,
355	    current: &mut Vec<String>,
356	    paths: &mut Vec<Vec<String>>,
357	) {
358	    match value {
359	        serde_json::Value::Object(map) => {
360	            if !current.is_empty() {
361	                paths.push(current.clone());
362	            }
363	            for (key, child) in map {
364	                // Skip underscore-prefixed keys (metadata fields like
365	                // `_introspection`) — they don't create child D-Bus objects.
366	                if key.starts_with('_') {
367	                    continue;
368	                }
369	                if child.is_object() || child.is_array() {
370	                    current.push(key.clone());
371	                    derive_paths_recursive(child, current, paths);
372	                    current.pop();
373	                }
374	            }
375	        }
376	        serde_json::Value::Array(arr) => {
377	            if !current.is_empty() {
378	                paths.push(current.clone());
379	            }
380	            for (idx, child) in arr.iter().enumerate() {
381	                if child.is_object() || child.is_array() {
382	                    let segment = ["id", "name", "label", "key", "path", "domain", "host"]
383	                        .iter()
384	                        .find_map(|&field| child.get(field).and_then(|v| v.as_str()))
385	                        .map(|s| s.replace(['/', ' ', ':'], "_"))
386	                        .unwrap_or_else(|| idx.to_string());
387	                    current.push(segment);
388	                    derive_paths_recursive(child, current, paths);
389	                    current.pop();
390	                }
391	            }
392	        }
393	        _ => {}
394	    }
395	}
396	
397	/// Manages the set of D-Bus objects served for all projections.
398	///
399	/// Each object reads its data 1:1 from the shm projection layer on every
400	/// property access. The server only tracks which paths are mounted (for
401	/// mount/unmount lifecycle); it holds no data copies.
402	pub struct ProjectionDbusServer {
403	    conn: Connection,
404	    /// Mounted object paths (shared with ProjectionRoot for refresh())
405	    objects: Arc<Mutex<HashSet<String>>>,
406	}
407	
408	impl ProjectionDbusServer {
409	    pub async fn new() -> Result<Self> {
410	        let objects = Arc::new(Mutex::new(HashSet::new()));
411	        let root = ProjectionRoot {
412	            objects: objects.clone(),
413	        };
414	
415	        let conn = match std::env::var("OP_DBUS_PROJECTION_BUS")
416	            .unwrap_or_else(|_| "system".to_string())
417	            .as_str()
418	        {
419	            "session" => {
420	                Builder::session()?
421	                    .serve_at("/org/opdbus/v1/plugins", root)?
422	                    .name(op_plugins::canonical::BASE_SERVICE_NAME)?
423	                    .build()
424	                    .await?
425	            }
426	            _ => {
427	                Builder::system()?
428	                    .serve_at("/org/opdbus/v1/plugins", root)?
429	                    .name(op_plugins::canonical::BASE_SERVICE_NAME)?
430	                    .build()
431	                    .await?
432	            }
433	        };
434	
435	        info!(
436	            service = op_plugins::canonical::BASE_SERVICE_NAME,
437	            "D-Bus plugin projection connection established"
438	        );
439	
440	        Ok(Self { conn, objects })
441	    }
442	
443	    pub async fn new_session() -> Result<Self> {
444	        let objects = Arc::new(Mutex::new(HashSet::new()));
445	        let root = ProjectionRoot {
446	            objects: objects.clone(),
447	        };
448	
449	        let conn = Builder::session()?
450	            .serve_at("/org/opdbus/v1/plugins", root)?
451	            .name(op_plugins::canonical::BASE_SERVICE_NAME)?
452	            .build()
453	            .await?;
454	
455	        info!(
456	            service = op_plugins::canonical::BASE_SERVICE_NAME,
457	            "D-Bus session plugin projection connection established"
458	        );
459	
460	        Ok(Self { conn, objects })
461	    }
462	
463	    /// Sync the D-Bus tree from shm. Mounts new objects, unmounts stale ones.
464	    /// Called on startup. At runtime, the `refresh()` D-Bus method does the same.
465	    pub async fn sync_from_shm(&self) -> Result<()> {
466	        let mut objects = self.objects.lock().await;
467	        sync_all_from_shm(&self.conn, &mut objects).await
468	    }
469	
470	    /// Ensure all known plugins have at least a root object mounted, even if
471	    /// no shm data exists yet (no mutations). Plugins with shm data get their
472	    /// full derived tree; plugins without shm get just the root (data returns `{}`).
473	    pub async fn seed_plugin_roots(&self, plugin_ids: &[String]) -> Result<()> {
474	        let mut objects = self.objects.lock().await;
475	        for plugin_id in plugin_ids {
476	            // If shm has data, sync the full derived tree.
477	            if let Some(paths) = read_and_derive_paths(plugin_id) {
478	                sync_plugin_paths(&self.conn, &mut objects, plugin_id, &paths).await?;
479	            } else {
480	                // No shm data — mount just the root so the plugin appears in the tree.
481	                let root_path = build_projected_path(plugin_id, &[]);
482	                if !objects.contains(&root_path) {
483	                    let obj = ProjectedObject {
484	                        plugin_id: plugin_id.to_string(),
485	                        path_segments: Vec::new(),
486	                    };
487	                    self.conn.object_server().at(root_path.as_str(), obj).await?;
488	                    objects.insert(root_path.clone());
489	                    debug!(path = root_path, "Seeded plugin root (no shm data yet)");
490	                }
491	            }
492	        }
493	        Ok(())
494	    }
495	
496	    /// Sync a single plugin's D-Bus objects to match the derived paths.
497	    pub async fn sync_plugin(&mut self, plugin_id: &str, paths: &[Vec<String>]) -> Result<()> {
498	        let mut objects = self.objects.lock().await;
499	        sync_plugin_paths(&self.conn, &mut objects, plugin_id, paths).await
500	    }
501	
502	    pub async fn object_count(&self) -> usize {
503	        self.objects.lock().await.len()
504	    }
505	
506	    /// Mount a projection as a D-Bus object (or emit `updated` if already mounted).
507	    pub async fn upsert(&mut self, plugin_id: &str, path_segments: &[String]) -> Result<()> {
508	        let path = build_projected_path(plugin_id, path_segments);
509	
510	        {
511	            let mut objects = self.objects.lock().await;
512	            if !objects.contains(&path) {
513	                let obj = ProjectedObject {
514	                    plugin_id: plugin_id.to_string(),
515	                    path_segments: path_segments.to_vec(),
516	                };
517	                self.conn.object_server().at(path.as_str(), obj).await?;
518	                objects.insert(path.clone());
519	                debug!(path, "Mounted D-Bus projection object");
520	            }
521	        }
522	
523	        // Emit updated signal with current shm data (push notification).
524	        let data = read_projected_data(plugin_id, path_segments);
525	        let iface_ref = self
526	            .conn
527	            .object_server()
528	            .interface::<_, ProjectedObject>(path.as_str())
529	            .await?;
530	        ProjectedObject::updated(iface_ref.signal_emitter(), &data).await?;
531	
532	        debug!(path, "Updated D-Bus projection object");
533	        Ok(())
534	    }
535	
536	    /// Remove a projection's D-Bus object.
537	    pub async fn remove(&mut self, plugin_id: &str, path_segments: &[String]) -> Result<()> {
538	        let path = build_projected_path(plugin_id, path_segments);
