/// Derive a **non-spoofable**, stable session id from the WireGuard peer's
/// **preshared key (PSK)** salted by its public key: `Argon2(secret = PSK,
/// salt = pubkey)`.
///
/// Why PSK, not just the pubkey: the public key is *public*, so hashing it
/// (the old `Blake3(pubkey)` derivation) is forgeable — anyone who knows the
/// peer's public key could compute its session id. The PSK is a genuine
/// per-peer secret that is never derivable from public data, so only a party
/// that actually holds the PSK can produce this id. The pubkey is the salt for
/// domain separation between peers.
///
/// Stable for the life of the account: PSK and pubkey are both stable, so the
/// same peer always yields the same id (re-auth after timeout resumes the same
/// logical session). Output is a UUID string so existing consumers (headers,
/// trace IDs, accountability page) are unchanged. Local-only: no network, no DB.
pub fn derive_session_id(pubkey: &str, psk: &[u8]) -> String {
    use argon2::Argon2;
    let mut bytes = [0u8; 16];
    Argon2::default()
        .hash_password_into(psk, pubkey.as_bytes(), &mut bytes)
        .expect("argon2 session-id derivation (salt = pubkey, >= 8 bytes)");
    Uuid::from_bytes(bytes).to_string()
}

