/// Fetch a peer's **preshared key (PSK)** — the shared secret that roots the
/// non-spoofable session id (see [`crate::session::derive_session_id`]).
///
/// Reads `wg show <iface> dump`; the first line is the interface, peer lines
/// are `pubkey \t preshared_key \t endpoint \t allowed_ips \t ...`. Returns
/// `Ok(None)` when the peer has no PSK configured (`(none)`), so the caller
/// can refuse to mint a spoofable session id rather than fall back to one.
pub fn get_psk_for_pubkey(&self, pubkey: &str) -> anyhow::Result<Option<String>> {
    let output = Command::new("wg")
        .args(["show", &self.interface, "dump"])
        .output()?;

    if !output.status.success() {
        return Ok(None);
    }

    let stdout = String::from_utf8_lossy(&output.stdout);
    // Skip the first (interface) line; match peers by pubkey in field 0.
    for line in stdout.lines().skip(1) {
        let parts: Vec<&str> = line.split('\t').collect();
        if parts.len() >= 2 && parts[0] == pubkey {
            let psk = parts[1].trim();
            if psk.is_empty() || psk == "(none)" {
                return Ok(None);
            }
            return Ok(Some(psk.to_string()));
        }
    }

    Ok(None)
}

