/// creation doesn't require a live `wg` peer. Mirrors a real per-peer secret.
const TEST_PSK: &str = "test-preshared-key-secret";

fn test_manager() -> (SessionManager, TempDir) {
    std::env::set_var("WG_PSK", TEST_PSK);
    let dir = TempDir::new().unwrap();
