//! Shared tonic TLS material — mandatory on ALL gRPC traffic (every server and
//! every client). Borrows the real Let's Encrypt wildcard cert for
//! `*.ghostbridge.tech` (full chain, publicly trusted — NOT self-signed), the
//! same cert xray's TLS inbounds present. There is no plaintext gRPC surface.
//!
//! Reality (the xray decoy) is unrelated: it borrows `www.microsoft.com`'s
//! handshake and uses no local cert. This module is only the genuine LE cert.

use anyhow::{Context, Result};
use std::path::PathBuf;
use tonic::transport::{ClientTlsConfig, Identity, ServerTlsConfig};

/// Full-chain cert and key, overridable via env. Defaults to the xray LE cert.
const DEFAULT_CERT: &str = "/etc/ssl/xray/ghostbridge.tech.pem";
const DEFAULT_KEY: &str = "/etc/ssl/xray/ghostbridge.tech.key";

/// Verification name clients use when dialing the bridge by IP (or unix socket):
/// matches the cert's `*.ghostbridge.tech` SAN so TLS validates without the IP
/// being in the cert. Overridable via `GHOSTBRIDGE_TLS_DOMAIN`.
const DEFAULT_TLS_DOMAIN: &str = "bridge.ghostbridge.tech";

fn cert_path() -> PathBuf {
    std::env::var("GHOSTBRIDGE_TLS_CERT")
        .unwrap_or_else(|_| DEFAULT_CERT.to_string())
        .into()
}

fn key_path() -> PathBuf {
    std::env::var("GHOSTBRIDGE_TLS_KEY")
        .unwrap_or_else(|_| DEFAULT_KEY.to_string())
        .into()
}

pub fn tls_domain() -> String {
    std::env::var("GHOSTBRIDGE_TLS_DOMAIN").unwrap_or_else(|_| DEFAULT_TLS_DOMAIN.to_string())
}

/// Server identity (full chain + private key) for every tonic gRPC server.
pub fn server_identity() -> Result<Identity> {
    let cert = cert_path();
    let key = key_path();
    let cert_pem = std::fs::read(&cert).with_context(|| format!("read TLS cert {cert:?}"))?;
    let key_pem = std::fs::read(&key).with_context(|| format!("read TLS key {key:?}"))?;
    Ok(Identity::from_pem(cert_pem, key_pem))
}

/// `ServerTlsConfig` for every tonic gRPC server. Mandatory — callers must apply
/// this (no `Option`): there is no plaintext gRPC.
pub fn server_tls_config() -> Result<ServerTlsConfig> {
    Ok(ServerTlsConfig::new().identity(server_identity()?))
}

/// `ClientTlsConfig` for every tonic gRPC client. The LE cert is publicly
/// trusted, so bundled webpki roots verify it; `domain_name` lets clients dial
/// by IP/unix-socket and still validate the `*.ghostbridge.tech` cert.
pub fn client_tls_config() -> ClientTlsConfig {
    ClientTlsConfig::new()
        .with_webpki_roots()
        .domain_name(tls_domain())
}

