15	/// Both `ring` and `aws-lc-rs` features are enabled transitively (ring via
16	/// reqwest/hyper-rustls, aws-lc-rs via tonic/tokio-rustls), so rustls cannot
17	/// auto-detect which to use. We explicitly select `ring` (lighter, no cmake/nasm
18	/// build dependency, already compiled as a transitive dep).
19	static CRYPTO_PROVIDER: OnceLock<()> = OnceLock::new();
