3	//! `*.ghostbridge.tech` (full chain, publicly trusted — NOT self-signed), the
4	//! same cert xray's TLS inbounds present. There is no plaintext gRPC surface.
5	//!
6	//! Reality (the xray decoy) is unrelated: it borrows `www.microsoft.com`'s
7	//! handshake and uses no local cert. This module is only the genuine LE cert.
8	
9	use anyhow::{Context, Result};
10	use std::path::PathBuf;
11	use std::sync::OnceLock;
12	use tonic::transport::{ClientTlsConfig, Endpoint, Identity, ServerTlsConfig};
13	
14	/// Install the rustls crypto provider exactly once at process startup.
15	/// Both `ring` and `aws-lc-rs` features are enabled transitively (ring via
16	/// reqwest/hyper-rustls, aws-lc-rs via tonic/tokio-rustls), so rustls cannot
17	/// auto-detect which to use. We explicitly select `ring` (lighter, no cmake/nasm
18	/// build dependency, already compiled as a transitive dep).
19	static CRYPTO_PROVIDER: OnceLock<()> = OnceLock::new();
20	
21	fn ensure_crypto_provider() {
22	    CRYPTO_PROVIDER.get_or_init(|| {
23	        let _ = rustls::crypto::ring::default_provider().install_default();
24	    });
25	}
26	
27	/// Full-chain cert and key, overridable via env. Defaults to the xray LE cert.
28	const DEFAULT_CERT: &str = "/etc/ssl/xray/ghostbridge.tech.pem";
29	const DEFAULT_KEY: &str = "/etc/ssl/xray/ghostbridge.tech.key";
30	
31	/// Verification name clients use when dialing the bridge by IP (or unix socket):
32	/// matches the cert's `*.ghostbridge.tech` SAN so TLS validates without the IP
33	/// being in the cert. Overridable via `GHOSTBRIDGE_TLS_DOMAIN`.
34	const DEFAULT_TLS_DOMAIN: &str = "bridge.ghostbridge.tech";
...
42	    let cert_pem = std::fs::read(&cert).with_context(|| format!("read TLS cert {cert:?}"))?;
43	    let key_pem = std::fs::read(&key).with_context(|| format!("read TLS key {key:?}"))?;
44	    Ok(Identity::from_pem(cert_pem, key_pem))
45	}
46	
47	/// `ServerTlsConfig` for every tonic gRPC server. Mandatory — callers must apply
48	/// this (no `Option`): there is no plaintext gRPC.
49	pub fn server_tls_config() -> Result<ServerTlsConfig> {
50	    ensure_crypto_provider();
51	    Ok(ServerTlsConfig::new().identity(server_identity()?))
52	}
53	
54	/// `ClientTlsConfig` for every tonic gRPC client. The LE cert is publicly
55	/// trusted, so bundled webpki roots verify it; `domain_name` lets clients dial
56	/// by IP/unix-socket and still validate the `*.ghostbridge.tech` cert.
57	pub fn client_tls_config() -> ClientTlsConfig {
58	    ensure_crypto_provider();
59	    ClientTlsConfig::new()
60	        .with_webpki_roots()
61	        .domain_name(tls_domain())
62	}
63	
64	/// Build a tonic `Endpoint` with mandatory TLS from any address form.
65	///
66	/// Normalises `http://host:port` → `https://host:port` (callers throughout the
67	/// codebase use `http://` URLs in env vars; TLS is still applied via
68	/// `tls_config`, but an `https` scheme is the canonical form). `unix:` and
69	/// `https:` endpoints are passed through. The returned endpoint has
70	/// [`client_tls_config`] applied — callers add timeouts / connectors as needed.
71	pub fn tls_endpoint(address: &str) -> Result<Endpoint> {
72	    let normalised = if let Some(rest) = address.strip_prefix("http://") {
73	        format!("https://{rest}")
74	    } else if address.starts_with("https://") || address.starts_with("unix:") {
75	        address.to_string()
76	    } else {
77	        // Bare host:port — prefix https://
78	        format!("https://{address}")
79	    };
80	    let endpoint = Endpoint::from_shared(normalised)
81	        .map_err(|e| anyhow::anyhow!("invalid gRPC endpoint '{address}': {e}"))?;
82	    endpoint
83	        .tls_config(client_tls_config())
84	        .map_err(|e| anyhow::anyhow!("TLS config for '{address}': {e}"))
85	}

