94	/// Canonical `unix_socket` schema, **derived** from the structs via schemars
95	/// (see [`super::schemars_adapter`]). `port` bounds, field descriptions (from
96	/// doc comments) and `required` flags all come from the type — the struct is
97	/// the single source of truth. The frozen hand-rolled `unix_socket_schema()`
98	/// (test-only) guards this against drift via `derived_schema_matches_hand_rolled`.
99	pub fn unix_socket_schema_derived() -> PluginSchema {
100	    let root = serde_json::to_value(schemars::schema_for!(UnixSocketState))
101	        .expect("schemars schema serializes to JSON");
102	    let mut schema = super::schemars_adapter::plugin_schema_from_json(
103	        "unix_socket",
104	        "1.0.0",
105	        "Single shared unix-domain socket for the tonic-web gRPC bridge — all services route through it, demuxed by domain/SNI at xray and by gRPC service/method at the bridge",
106	        &root,
107	    );
108	    super::common::oscal::ensure_category_metadata_fields(&mut schema);
109	    // The createunixsocket action (mut.service.unix-socket.create-socket@v1):
110	    // register a container/service on the shared container.sock. D-Bus/gRPC
111	    // method signatures derive from the schema; this subid is the OSCAL handle.
112	    schema.subids.insert(
113	        "createunixsocket".to_string(),
114	        "mut.service.unix-socket.create-socket@v1".to_string(),
115	    );
116	    schema
117	}
