278	impl StatePlugin for UnixSocketPlugin {
279	    fn name(&self) -> &str {
280	        "unix_socket"
281	    }
282	
283	    fn version(&self) -> &str {
284	        "1.0.0"
285	    }
286	
287	    fn schema(&self) -> Option<op_state_store::PluginSchema> {
288	        let mut schema = unix_socket_schema_derived();
289	        super::common::oscal::ensure_category_metadata_fields(&mut schema);
290	        Some(schema)
291	    }
292	
293	    async fn calculate_diff(&self, _current: &Value, _desired: &Value) -> Result<StateDiff> {
294	        // No diff loop: the schema-declared state is authoritative and applied
295	        // wholesale by `apply_state`.
296	        Ok(StateDiff {
297	            plugin: self.name().to_string(),
298	            actions: vec![],
299	            metadata: DiffMetadata {
300	                timestamp: chrono::Utc::now().timestamp(),
301	                current_hash: "schema".to_string(),
302	                desired_hash: "schema".to_string(),
303	            },
304	        })
305	    }
306	
307	    async fn apply_state(&self, _diff: &StateDiff) -> Result<ApplyResult> {
308	        // Reconcile the live unix sockets to exactly the schema-declared set.
309	        let desired = Self::read_desired();
310	        Ok(self.reconcile(&desired))
311	    }
312	
313	    async fn verify_state(&self, _desired: &Value) -> Result<bool> {
314	        let desired = Self::read_desired();
315	        let active = self.active.lock();
316	        let satisfied = desired.sockets.iter().all(|endpoint| {
317	            active.contains_key(&endpoint.path) && Path::new(&endpoint.path).exists()
318	        });
319	        Ok(satisfied)
320	    }
321	
322	    async fn create_checkpoint(&self) -> Result<Checkpoint> {
323	        Ok(Checkpoint {
324	            id: uuid::Uuid::new_v4().to_string(),
325	            plugin: self.name().to_string(),
326	            timestamp: chrono::Utc::now().timestamp(),
327	            state_snapshot: simd_json::serde::to_owned_value(Self::read_desired())?,
328	            backend_checkpoint: None,
329	        })
330	    }
331	
332	    async fn rollback(&self, checkpoint: &Checkpoint) -> Result<()> {
333	        let snapshot = simd_json::serde::from_owned_value::<UnixSocketState>(
334	            checkpoint.state_snapshot.clone(),
335	        )
336	        .unwrap_or_default();
337	        self.reconcile(&snapshot);
338	        Ok(())
339	    }
340	
341	    fn capabilities(&self) -> PluginCapabilities {
342	        PluginCapabilities {
343	            supports_rollback: true,
344	            supports_checkpoints: true,
345	            supports_verification: true,
346	            atomic_operations: false,
347	        }
348	    }
349	}
