375	    /// The schemars-derived schema must match the hand-rolled one field-for-field.
376	    #[test]
377	    fn derived_schema_matches_hand_rolled() {
378	        let hand = unix_socket_schema();
379	        let derived = unix_socket_schema_derived();
380	
381	        assert_eq!(derived.name, hand.name);
382	        assert_eq!(derived.version, hand.version);
