384	        let hp = sockets_object(&hand);
385	        let dp = sockets_object(&derived);
386	
387	        let mut hk: Vec<_> = hp.keys().cloned().collect();
388	        let mut dk: Vec<_> = dp.keys().cloned().collect();
389	        hk.sort();
390	        dk.sort();
391	        assert_eq!(dk, hk, "derived inner fields must match hand-rolled");
392	
393	        // ports: Array (derived from `Vec<u16>`)
394	        assert!(matches!(dp["ports"].field_type, FieldType::Array(_)));
395	
396	        // doc comments survive as descriptions
397	        assert!(!dp["path"].description.is_empty());
398	        // required set: path only (name/ports/protocol/label have serde defaults)
399	        assert!(dp["path"].required);
400	        assert!(
401	            !dp["name"].required
402	                && !dp["ports"].required
403	                && !dp["protocol"].required
404	                && !dp["label"].required
405	        );
406	
407	        // OSCAL subids are preserved at the schema and field level.
408	        assert_eq!(
409	            derived.subids.get("__schema__"),
410	            Some(&"sch.software.plugin.unix-socket.schema@v1".to_string())
411	        );
412	        assert_eq!(
413	            derived.subids.get("sockets"),
