430	        assert_eq!(
431	            sockets.get("x-oscal-subid").and_then(|v| v.as_str()),
432	            Some("mut.service.unix-socket.bind@v1")
433	        );
434	
435	        let endpoint_def = raw
436	            .get("$defs")
437	            .or_else(|| raw.get("definitions"))
438	            .and_then(|d| d.get("SocketEndpoint"))
439	            .expect("SocketEndpoint $def");
440	        let props = endpoint_def
441	            .get("properties")
442	            .expect("SocketEndpoint properties");
443	
444	        let expected = [
445	            ("name", "mut.service.unix-socket.bind-name@v1"),
446	            ("path", "mut.service.unix-socket.bind-path@v1"),
447	            ("ports", "mut.service.unix-socket.bind-port@v1"),
448	            ("protocol", "mut.service.unix-socket.bind-protocol@v1"),
449	            ("label", "mut.service.unix-socket.bind-label@v1"),
450	        ];
451	        for (field, subid) in expected {
452	            let actual = props
453	                .get(field)
454	                .and_then(|f| f.get("x-oscal-subid"))
455	                .and_then(|v| v.as_str());
456	            assert_eq!(actual, Some(subid), "subid mismatch for {field}");
457	        }
458	    }
459	
460	    #[test]
461	    fn should_bind_and_unbind_declared_sockets() {
462	        let dir = tempfile::tempdir().expect("tempdir");
463	        let plugin = UnixSocketPlugin::new();
464	
465	        let ep = endpoint(dir.path(), "qdrant.sock", 6334);
466	        let desired = UnixSocketState {
467	            sockets: vec![ep.clone()],
468	        };
469	
470	        let result = plugin.reconcile(&desired);
471	        assert!(result.success, "errors: {:?}", result.errors);
472	        assert!(std::path::Path::new(&ep.path).exists());
473	        assert!(plugin.active.lock().contains_key(&ep.path));
474	
475	        // Reconciling to an empty set tears the socket down.
476	        let cleared = plugin.reconcile(&UnixSocketState::default());
477	        assert!(cleared.success);
478	        assert!(!std::path::Path::new(&ep.path).exists());
479	        assert!(plugin.active.lock().is_empty());
480	    }
481	
482	    #[test]
483	    fn should_be_idempotent_for_already_bound_sockets() {
484	        let dir = tempfile::tempdir().expect("tempdir");
485	        let plugin = UnixSocketPlugin::new();
486	        let desired = UnixSocketState {
487	            sockets: vec![
488	                endpoint(dir.path(), "a.sock", 1),
489	                endpoint(dir.path(), "b.sock", 2),
490	            ],
491	        };
492	
493	        let first = plugin.reconcile(&desired);
494	        assert_eq!(first.changes_applied.len(), 2);
495	
496	        // Second reconcile against the same desired set creates nothing new.
497	        let second = plugin.reconcile(&desired);
498	        assert!(second.changes_applied.is_empty());
499	        assert_eq!(plugin.active.lock().len(), 2);
500	    }
501	}
