505	/// matches the contract this plugin shipped with. Production uses
506	/// [`unix_socket_schema_derived`].
507	#[cfg(test)]
508	pub(crate) fn unix_socket_schema() -> PluginSchema {
509	    let mut socket_fields = HashMap::new();
