527	        FieldSchema {
528	            field_type: FieldType::String,
529	            required: true,
530	            description: "Filesystem path of the shared unix domain socket".to_string(),
531	            default: None,
532	            example: Some(json!("/run/ghostbridge/container.sock")),
533	            constraints: Vec::new(),
534	            read_only: false,
535	            read_only_when: None,
536	        },
537	    );
538	    socket_fields.insert(
539	        "ports".to_string(),
540	        FieldSchema {
541	            field_type: FieldType::Array(Box::new(FieldType::Integer)),
542	            required: false,
543	            description:
544	                "Backend TCP ports the container serves (metadata; tonic-web demuxes by reflection)"
545	                    .to_string(),
546	            default: Some(json!([])),
547	            example: Some(json!([25, 465, 587])),
548	            constraints: Vec::new(),
549	            read_only: false,
550	            read_only_when: None,
551	        },
552	    );
553	    socket_fields.insert(
554	        "protocol".to_string(),
555	        FieldSchema {
556	            field_type: FieldType::String,
557	            required: false,
558	            description: "Transport protocol carried over the socket (grpc, jsonrpc, …)"
559	                .to_string(),
560	            default: Some(json!("grpc")),
561	            example: None,
562	            constraints: Vec::new(),
563	            read_only: false,
564	            read_only_when: None,
565	        },
566	    );
567	    socket_fields.insert(
568	        "label".to_string(),
569	        FieldSchema {
570	            field_type: FieldType::String,
571	            required: false,
572	            description: "Human-readable label for the shared socket".to_string(),
573	            default: Some(json!("")),
574	            example: Some(json!("ghostbridge")),
575	            constraints: Vec::new(),
576	            read_only: false,
577	            read_only_when: None,
578	        },
579	    );
580	
581	    PluginSchema::builder("unix_socket")
582	        .version("1.0.0")
583	        .description("Single shared unix-domain socket for the tonic-web gRPC bridge — all services route through it, demuxed by domain/SNI at xray and by gRPC service/method at the bridge")
584	        .subid("__schema__", "sch.software.plugin.unix-socket.schema@v1")
585	        .array_field(
586	            "sockets",
587	            FieldType::Object(socket_fields),
588	            true,
589	            "The shared socket endpoint (one socket, all services route through it by domain)",
590	        )
591	        .subid("sockets", "mut.service.unix-socket.bind@v1")
592	        .example(json!({
593	            "sockets": [
594	                {
595	                    "name": "netmaker",
596	                    "path": "/run/ghostbridge/container.sock",
597	                    "ports": [18081, 1883, 8883],
598	                    "protocol": "grpc",
599	                    "label": "ghostbridge"
600	                }
601	            ]
602	        }))
603	        .build()
