283	/// Translate a Gemma backend into an OpenFlow rule for the bridge.
284	/// Only TCP/GRPC backends produce IP/Port matchable rules here; Unix sockets
285	/// route through the tonic-web gRPC bridge (reflection demuxes) so no OVS
286	/// bridge match is needed.
287	fn backend_to_openflow_rule(tag: &str, backend: &BackendSpec) -> Option<OpenFlowRule> {
288	    let (host, port) = match backend {
289	        BackendSpec::Tcp { host, port } => (host.clone(), *port),
290	        BackendSpec::Grpc { host, port, .. } => (host.clone(), *port),
291	        BackendSpec::Ingress
292	        | BackendSpec::Unix { .. }
293	        | BackendSpec::Dns { .. }
294	        | BackendSpec::File { .. }
295	        | BackendSpec::Internal => return None,
296	    };
297	
298	    let mut match_fields = HashMap::new();
299	    match_fields.insert("dl_type".to_string(), "0x0800".to_string());
300	    match_fields.insert("nw_proto".to_string(), "6".to_string()); // TCP
301	    match_fields.insert("nw_dst".to_string(), host.clone());
302	    match_fields.insert("tp_dst".to_string(), port.to_string());
303	
304	    Some(OpenFlowRule {
305	        priority: 150,
306	        match_fields,
307	        actions: vec!["output:ovsbr0-mgmt".to_string()],
308	        description: Some(format!("Gemma: {tag} -> host backend {host}:{port}")),
309	    })
310	}
311	
312	fn write_json<P: AsRef<Path>>(path: P, value: &XrayRoutingMap) -> Result<()> {
313	    let tmp = format!("{}.tmp", path.as_ref().display());
314	    let mut f =
315	        fs::File::create(&tmp).with_context(|| format!("failed to create tmp file: {tmp}"))?;
316	    let json =
317	        serde_json::to_string_pretty(value).with_context(|| "failed to serialize routing map")?;
318	    f.write_all(json.as_bytes())
319	        .with_context(|| format!("failed to write tmp file: {tmp}"))?;
320	    f.sync_data()
321	        .with_context(|| format!("failed to sync tmp file: {tmp}"))?;
322	    fs::rename(&tmp, path.as_ref())
323	        .with_context(|| format!("failed to rename {tmp} to {}", path.as_ref().display()))?;
324	    Ok(())
325	}
