193	/// Root interface at `/org/opdbus/v1/plugins`.
194	///
195	/// Always present so D-Bus introspection works even with zero plugins mounted.
196	/// The `plugins` property reads shm live. The `refresh()` method re-reads shm
197	/// and syncs the D-Bus tree (mount/unmount objects to match). This is the
198	/// dynamic-mount mechanism: no gRPC, no polling, no inotify — the tree is
199	/// derived on demand.
200	pub struct ProjectionRoot {
201	    objects: Arc<Mutex<HashSet<String>>>,
202	}
203	
204	#[interface(name = "org.opdbus.v1.plugins.ProjectionRoot")]
205	impl ProjectionRoot {
206	    /// List of plugin IDs currently projected in shm (live read).
207	    #[zbus(property)]
208	    async fn plugins(&self) -> Vec<String> {
209	        op_core::projection_shm::list_projected_plugins()
210	    }
211	
212	    /// Number of D-Bus objects currently mounted.
213	    #[zbus(property)]
214	    async fn object_count(&self) -> u64 {
215	        self.objects.lock().await.len() as u64
216	    }
217	
218	    /// Re-read shm and sync the D-Bus tree. Mounts new objects, unmounts stale
219	    /// ones. Returns the total object count after refresh.
220	    ///
221	    /// Call this after a mutation has written new state to shm. The
222	    /// MutationEngine can call this via D-Bus after writing to shm, or any
223	    /// client can call it to force a tree refresh.
224	    async fn refresh(&self, #[zbus(connection)] conn: &Connection) -> u64 {
225	        let mut objects = self.objects.lock().await;
226	        match sync_all_from_shm(conn, &mut objects).await {
227	            Ok(()) => objects.len() as u64,
228	            Err(e) => {
229	                tracing::warn!(error = %e, "refresh() failed");
230	                objects.len() as u64
231	            }
232	        }
233	    }
234	}
