1	//! Projection Server: pure read-through D-Bus projection of the plugin tree.
2	//!
3	//! Mounts the projected plugin tree at `org.opdbus.v1.plugins` and serves
4	//! each plugin's state as a `ProjectedObject` that reads 1:1 from the shm
5	//! projection layer (`/dev/shm/opdbus/projections/<plugin>.json`).
6	//!
7	//! The MutationEngine (the single write door) writes each plugin's full state
8	//! to shm on every mutation. This server mounts the tree from shm on startup
9	//! and exposes a `refresh()` D-Bus method on the root interface that re-reads
10	//! shm and syncs the tree (mount/unmount). No gRPC subscription, no polling,
11	//! no inotify — the tree is derived on demand.
12	
13	use anyhow::{Context, Result};
14	use op_projection::*;
15	use tracing::{info, warn};
16	use tracing_subscriber::{EnvFilter, FmtSubscriber};
17	
18	#[tokio::main]
19	async fn main() -> Result<()> {
20	    let subscriber = FmtSubscriber::builder()
21	        .with_env_filter(EnvFilter::from_default_env())
22	        .finish();
23	    tracing::subscriber::set_global_default(subscriber)?;
24	
25	    info!("Starting Operation-DBus Projection Server (read-through)");
26	
27	    // 1. Initialize Schema Engine + discover plugin schemas (writes to shm).
28	    let mut schema_engine = SchemaEngine::new();
29	
30	    let plugin_reader = match SystemPluginReader::new().await {
31	        Ok(reader) => reader,
32	        Err(error) => {
33	            warn!(
34	                error = %error,
35	                "Failed to initialize plugin reader; continuing with empty schema catalog"
36	            );
37	            SystemPluginReader::empty()
38	        }
39	    };
40	
41	    for schema in plugin_reader.projection_schemas() {
42	        register_schema_if_missing(&mut schema_engine, schema)?;
43	    }
44	
45	    info!(
46	        schemas = schema_engine.list_schemas().len(),
47	        "Schema catalog published to shm"
48	    );
49	
50	    // 2. Initialize D-Bus server (owns org.opdbus.v1.plugins, root interface
51	    //    at /org/opdbus/v1/plugins is always present for introspection).
52	    let dbus_server = ProjectionDbusServer::new()
53	        .await
54	        .context("failed to start projection D-Bus server")?;
55	
56	    // 3. Initial tree sync: mount from shm (mutations) then seed all known
57	    //    plugin roots from the schema catalog so the tree is never empty.
58	    dbus_server.sync_from_shm().await?;
59	
60	    let known_plugins: Vec<String> = plugin_reader
61	        .projection_schemas()
62	        .iter()
63	        .map(|s| s.name.clone())
64	        .collect();
65	    dbus_server.seed_plugin_roots(&known_plugins).await?;
66	
67	    let count = dbus_server.object_count().await;
68	    info!(objects = count, plugins = known_plugins.len(), "Initial tree sync complete");
69	
70	    // 4. Initialize JSON-stream server (for WebSocket clients).
71	    let mut stream_server = ProjectionStreamServer::new();
72	    stream_server.start(8082)?;
73	
74	    // 5. Run forever. The tree is derived on-demand via the `refresh()` D-Bus
75	    //    method on the ProjectionRoot interface. No gRPC, no polling.
76	    info!("Projection server ready — tree syncs on refresh() D-Bus call or restart");
77	    tokio::signal::ctrl_c().await?;
78	
79	    Ok(())
80	}
81	
82	fn register_schema_if_missing(
83	    schema_engine: &mut SchemaEngine,
84	    schema: PluginSchema,
85	) -> Result<()> {
86	    if schema_engine.has_valid_schema(&schema.name) {
87	        return Ok(());
88	    }
89	
90	    let schema_name = schema.name.clone();
91	    schema_engine
92	        .register_schema(schema)
93	        .with_context(|| format!("failed to register projection schema '{}'", schema_name))?;
94	    Ok(())
95	}
