22	};
23	
24	/// Configuration for a remote gRPC endpoint
25	#[derive(Debug, Clone)]
26	pub struct RemoteEndpoint {
27	    pub address: String,
28	    pub tls_enabled: bool,
29	    pub connect_timeout: Duration,
30	    pub request_timeout: Duration,
31	}
32	
33	impl Default for RemoteEndpoint {
34	    fn default() -> Self {
35	        Self {
36	            address: "http://127.0.0.1:50051".to_string(),
37	            tls_enabled: false,
38	            connect_timeout: Duration::from_secs(5),
39	            request_timeout: Duration::from_secs(30),
40	        }
41	    }
42	}
43	
44	/// gRPC client pool for connecting to remote Operation services
45	pub struct GrpcClientPool {
46	    /// Map of endpoint address to channel
47	    channels: RwLock<HashMap<String, Channel>>,
48	    /// Default endpoint configuration
49	    default_config: RemoteEndpoint,
50	}
51	
52	impl Default for GrpcClientPool {
53	    fn default() -> Self {
54	        Self::new()
55	    }
56	}
57	
58	impl GrpcClientPool {
59	    pub fn new() -> Self {
60	        Self {
61	            channels: RwLock::new(HashMap::new()),
62	            default_config: RemoteEndpoint::default(),
63	        }
64	    }
65	
66	    pub fn with_default_config(config: RemoteEndpoint) -> Self {
67	        Self {
68	            channels: RwLock::new(HashMap::new()),
69	            default_config: config,
70	        }
71	    }
72	
73	    /// Get or create a channel to the specified address (supports comma-separated endpoints for load balancing)
74	    async fn get_channel(&self, address: &str) -> Result<Channel, GrpcClientError> {
75	        {
76	            let channels = self.channels.read().await;
77	            if let Some(channel) = channels.get(address) {
78	                return Ok(channel.clone());
79	            }
80	        }
81	
82	        let addrs: Vec<&str> = address
83	            .split(',')
84	            .map(|s| s.trim())
85	            .filter(|s| !s.is_empty())
86	            .collect();
87	
88	        let channel = if addrs.len() > 1 {
89	            // Native Tonic Load Balancing
90	            let endpoints = addrs
91	                .into_iter()
92	                .map(|addr| {
93	                    Endpoint::from_shared(addr.to_string()).map(|e| {
94	                        e.connect_timeout(self.default_config.connect_timeout)
95	                            .timeout(self.default_config.request_timeout)
96	                    })
97	                })
98	                .collect::<Result<Vec<_>, _>>()
99	                .map_err(|e| {
100	                    GrpcClientError::ConnectionFailed(format!("Invalid endpoint: {}", e))
101	                })?;
102	
103	            Channel::balance_list(endpoints.into_iter())
104	        } else {
105	            // Single endpoint
106	            let endpoint = Endpoint::from_shared(address.to_string())
107	                .map_err(|e| GrpcClientError::ConnectionFailed(e.to_string()))?
108	                .connect_timeout(self.default_config.connect_timeout)
109	                .timeout(self.default_config.request_timeout);
110	
111	            endpoint
112	                .connect()
113	                .await
114	                .map_err(|e| GrpcClientError::ConnectionFailed(e.to_string()))?
115	        };
116	
117	        {
118	            let mut channels = self.channels.write().await;
119	            channels.insert(address.to_string(), channel.clone());
120	        }
121	
122	        info!("Connected to remote gRPC endpoint(s): {}", address);
123	        Ok(channel)
124	    }
125	
126	    /// Get a Plugin service client
127	    pub async fn plugin_service_client(
128	        &self,
129	        address: &str,
130	    ) -> Result<PluginServiceClient<Channel>, GrpcClientError> {
131	        let channel = self.get_channel(address).await?;
132	        Ok(PluginServiceClient::new(channel))
133	    }
134	
135	    /// Get a StateSync service client
136	    pub async fn state_sync_client(
137	        &self,
138	        address: &str,
139	    ) -> Result<StateSyncClient<Channel>, GrpcClientError> {
140	        let channel = self.get_channel(address).await?;
141	        Ok(StateSyncClient::new(channel))
142	    }
143	
144	    /// Get an EventChain service client
145	    pub async fn event_chain_client(
146	        &self,
147	        address: &str,
148	    ) -> Result<EventChainServiceClient<Channel>, GrpcClientError> {
149	        let channel = self.get_channel(address).await?;
150	        Ok(EventChainServiceClient::new(channel))
151	    }
152	
153	    /// Close all connections
154	    pub async fn close_all(&self) {
155	        let mut channels = self.channels.write().await;
156	        channels.clear();
157	        info!("Closed all gRPC client connections");
158	    }
159	}
