#[test]
fn derive_session_id_is_deterministic_and_uuid_like() {
    // Non-spoofable: same (pubkey, PSK) → same id; different pubkey OR
    // different PSK → different id.
    let id1 = derive_session_id("test-pubkey", TEST_PSK.as_bytes());
    let id2 = derive_session_id("test-pubkey", TEST_PSK.as_bytes());
    let id3 = derive_session_id("different-pubkey", TEST_PSK.as_bytes());
    let id4 = derive_session_id("test-pubkey", b"a-different-psk");
    assert_eq!(id1, id2);
    assert_ne!(id1, id3);
    assert_ne!(id1, id4, "a different PSK must yield a different id");
    // Uuid::parse_str accepts both hyphenated and raw hex forms; our output is hyphenated.
    assert!(uuid::Uuid::parse_str(&id1).is_ok());
}

