for (env, key) in [
    ("GHOSTBRIDGE_FOOTPRINT", "x-ghostbridge-footprint"),
    ("GHOSTBRIDGE_TRACE_ID", "x-ghostbridge-trace-id"),
] {
    if let Ok(v) = std::env::var(env) {
        if !headers.iter().any(|(k, _)| k == key) {
            headers.push((key.to_string(), v));
        }
    }
}
// Direct connections (no in-path xray injection): auto-stamp the Ghostbridge
// identity from the live sled — the SAME values the bridge interceptor
// validates (footprint == hex(hashed_footprint)). `--header`/env override.
if !headers.iter().any(|(k, _)| k == "x-ghostbridge-footprint") {
    if let Ok((sled_ptr, _mmap)) = op_identity::read_sled() {
        // SAFETY: pointer is valid for the lifetime of the held mmap; we copy
        // the fields out before `_mmap` drops at the end of this block.
        let sled = unsafe { &*sled_ptr };
        headers.push((
            "x-ghostbridge-footprint".to_string(),
            hex::encode(sled.hashed_footprint),
        ));
        if !headers.iter().any(|(k, _)| k == "x-ghostbridge-trace-id") {
            headers.push(("x-ghostbridge-trace-id".to_string(), sled.trace_id_hex()));
        }
        eprintln!("op-mcp-shim: stamped Ghostbridge identity from sled");
    } else {
        eprintln!("op-mcp-shim: WARNING no identity sled — calls may be Unauthenticated");
    }
}

