// op-tls inbound fallbacks. Plain HTTPS (browser/curl) to a subdomain is NOT
// vless, so the vless inbound falls back BY SNI: TCP/HTTP host services
// (qdrant, cozo, dashboard, …) fall back straight to their `host:port`; the
// catch-all default goes to the gRPC bridge. (Routing rules only fire for
// vless-decrypted traffic, so HTTP clients must be served via fallbacks.)
let mut fallback_entries: Vec<String> = routes
    .iter()
    .filter_map(|r| match &r.backend {
        GemmaBackend::Tcp { host, port } if !r.subdomains.is_empty() => Some(
            r.subdomains
                .iter()
                .map(|sd| format!(r#"{{ "name": "{sd}", "dest": "{host}:{port}" }}"#))
                .collect::<Vec<_>>()
                .join(", "),
        ),
        _ => None,
    })
    .collect();
if let Some((_, port)) = &bridge {
    fallback_entries.push(format!(r#"{{ "dest": {port} }}"#)); // catch-all, last
}
let bridge_fallback = fallback_entries.join(", ");

