#!/usr/bin/env node
// @ghostbridge/cognitive-mcp — universal cognitive-mcp client.
//
//   cognitive-mcp            run as an MCP stdio server (wraps op-mcp-shim;
//                            sled identity auto-stamped; no OAuth, no cloud)
//   cognitive-mcp install    detect installed clients + write the uniform
//                            cognitive-mcp entry into each (preserves others)
//   cognitive-mcp print      print the entry without writing
//
// One stdio entry for EVERY client (Claude Code, codex, cursor, junie,
// factory, gemini-cli). Env: COGNITIVE_MCP_SHIM, COGNITIVE_MCP_ENDPOINT.
'use strict';
const fs = require('fs');
const path = require('path');
const os = require('os');
const { spawnSync } = require('child_process');

const HOME = os.homedir();
const SERVER_KEY = 'cognitive-mcp';
const SHIM = process.env.COGNITIVE_MCP_SHIM || '/usr/local/bin/op-mcp-shim';
const ENDPOINT = process.env.COGNITIVE_MCP_ENDPOINT || 'https://100.90.37.2:50051';
// The uniform stdio entry every client gets.
const ENTRY = { command: 'npx', args: ['-y', '@ghostbridge/cognitive-mcp'] };

function run() {
  if (!fs.existsSync(SHIM)) {
    console.error(`cognitive-mcp: shim not found at ${SHIM} (set COGNITIVE_MCP_SHIM)`);
    process.exit(127);
  }
  const r = spawnSync(SHIM, ['--endpoint', ENDPOINT, '--service', 'PluginService'], { stdio: 'inherit' });
  process.exit(r.status == null ? 1 : r.status);
}

// ---- installer ----------------------------------------------------------
const CLIENTS = [
  { name: 'claude-code', file: path.join(process.cwd(), '.mcp.json'), fmt: 'json' },
  { name: 'cursor', file: path.join(HOME, '.cursor/mcp.json'), fmt: 'json' },
  { name: 'junie', file: path.join(HOME, '.junie/mcp/mcp.json'), fmt: 'json' },
  { name: 'factory', file: path.join(HOME, '.factory/mcp.json'), fmt: 'json' },
  { name: 'gemini-cli', file: path.join(HOME, '.gemini/settings.json'), fmt: 'json' },
  { name: 'codex', file: path.join(HOME, '.codex/config.toml'), fmt: 'toml' },
];

function readJsonLenient(p) {
  if (!fs.existsSync(p)) return {};
  let s = fs.readFileSync(p, 'utf8');
  // strip // and /* */ comments (JSONC, e.g. junie) for parsing
  s = s.replace(/\/\*[\s\S]*?\*\//g, '').replace(/(^|[^:])\/\/.*$/gm, '$1');
  try { return JSON.parse(s || '{}'); } catch (e) { return { __parse_error: String(e) }; }
}

function writeJsonClient(p) {
  const obj = readJsonLenient(p);
  if (obj.__parse_error) return `skip (unparseable JSON: ${obj.__parse_error})`;
  obj.mcpServers = obj.mcpServers || {};
  obj.mcpServers[SERVER_KEY] = { ...ENTRY };
  fs.mkdirSync(path.dirname(p), { recursive: true });
  fs.writeFileSync(p, JSON.stringify(obj, null, 2) + '\n');
  return 'wrote';
}

function writeTomlCodex(p) {
  let s = fs.existsSync(p) ? fs.readFileSync(p, 'utf8') : '';
  // remove any existing [mcp_servers.cognitive-mcp] block (and its .env)
  s = s.replace(/(^|\n)\[mcp_servers\.cognitive-mcp\][\s\S]*?(?=\n\[|\n*$)/g, '\n').replace(/\n{3,}/g, '\n\n');
  const argsToml = ENTRY.args.map(a => `"${a}"`).join(', ');
  const block = `\n[mcp_servers.cognitive-mcp]\ncommand = "${ENTRY.command}"\nargs = [${argsToml}]\n`;
  fs.mkdirSync(path.dirname(p), { recursive: true });
  fs.writeFileSync(p, s.replace(/\s*$/, '') + '\n' + block);
  return 'wrote';
}

function install(opts) {
  const onlyExisting = !opts.all;
  console.error(`cognitive-mcp install → entry: ${JSON.stringify(ENTRY)} (endpoint ${ENDPOINT})`);
  for (const c of CLIENTS) {
    const exists = fs.existsSync(c.file) || fs.existsSync(path.dirname(c.file));
    if (onlyExisting && !exists) { console.error(`  ${c.name.padEnd(12)} skip (not present)`); continue; }
    let res;
    try { res = c.fmt === 'toml' ? writeTomlCodex(c.file) : writeJsonClient(c.file); }
    catch (e) { res = `error: ${e.message}`; }
    console.error(`  ${c.name.padEnd(12)} ${res}  → ${c.file}`);
  }
  console.error('done. (Uses the global/published @ghostbridge/cognitive-mcp via npx.)');
}

const cmd = process.argv[2];
if (cmd === 'install') install({ all: process.argv.includes('--all') });
else if (cmd === 'print') console.log(JSON.stringify({ mcpServers: { [SERVER_KEY]: ENTRY } }, null, 2));
else run();

