nix = { version = "0.31.1", features = ["fs"] }
prost = "0.14.3"
tokio = { version = "1.49.0", features = ["full", "io-std"] }
tokio-stream = { version = "0.1.18", features = ["full"] }
tokio-util = { version = "0.7.18", features = ["full"] }
tonic = "0.14.3"
