1	//! Schema-Driven Dynamic gRPC Router
2	//!
3	//! Reads the live schema catalog from `/dev/shm/live-schema.json` and
4	//! dynamically routes incoming gRPC calls to their corresponding D-Bus
5	//! objects at `/org/opdbus/v1/plugins/<plugin>`.
6	//!
7	//! This replaces the need for hand-rolled per-plugin gRPC service
8	//! implementations. Every plugin defined in the schema catalog is
9	//! automatically exposed as a gRPC-callable service through the bridge.
10	//!
11	//! ## Architecture
12	//!
13	//! ```text
14	//! gRPC Client ──► SchemaRouter ──► D-Bus Object
15	//!                     │                  │
16	//!                     ├─ reads schema    │
17	//!                     │  from SHM        │
18	//!                     │                  │
19	//!                     └─ validates args  │
20	//!                        against schema  │
21	//! ```
22	//!
23	//! The router uses the existing `DbusPassthrough` transport but automatically
24	//! fills in the destination, path, and interface from the schema — so callers
25	//! only need to specify `plugin_id` and `method_name`.
26	
27	use std::collections::HashMap;
28	use std::sync::Arc;
29	
30	use serde_json::Value as JsonValue;
31	use tokio::sync::RwLock;
32	use tracing::{debug, info, warn};
33	use zbus::{Connection, Proxy};
34	
35	use op_plugins::canonical::{BASE_SERVICE_NAME, PLUGIN_BASE_PATH};
36	
37	/// The single active-schema catalog in shared memory.
38	const LIVE_SCHEMA_PATH: &str = "/dev/shm/live-schema.json";
39	
40	/// A schema-derived route entry for a plugin.
41	#[derive(Debug, Clone)]
42	pub struct PluginRoute {
43	    /// Plugin identifier (e.g. "unix_socket", "qdrant", "wireguard").
44	    pub plugin_id: String,
45	    /// Canonical D-Bus object path: `/org/opdbus/v1/plugins/<plugin_id>`.
46	    pub dbus_path: String,
47	    /// Canonical D-Bus destination (bus name): `org.opdbus.v1`.
48	    pub dbus_destination: String,
49	    /// Canonical D-Bus interface: `org.opdbus.v1.Plugin.<PluginName>`.
50	    pub dbus_interface: String,
51	    /// Methods declared in the schema (name → argument JSON schema).
52	    pub methods: HashMap<String, JsonValue>,
53	    /// Properties declared in the schema (name → field schema).
54	    pub properties: HashMap<String, JsonValue>,
55	}
56	
57	/// The dynamic schema router that maps plugin_id → D-Bus route.
58	pub struct SchemaRouter {
59	    /// Plugin routes keyed by plugin_id.
60	    routes: Arc<RwLock<HashMap<String, PluginRoute>>>,
61	    /// D-Bus system connection (shared with SchemaEngine).
62	    dbus_connection: Arc<tokio::sync::OnceCell<Connection>>,
63	}
64	
65	impl SchemaRouter {
66	    /// Create a new SchemaRouter and load routes from the live schema catalog.
67	    pub fn new(dbus_connection: Arc<tokio::sync::OnceCell<Connection>>) -> Self {
68	        let router = Self {
69	            routes: Arc::new(RwLock::new(HashMap::new())),
70	            dbus_connection,
71	        };
72	        // Perform initial load synchronously (best-effort at startup).
73	        let routes = Self::load_routes_from_shm();
74	        let rt = router.routes.clone();
75	        tokio::spawn(async move {
76	            let mut w = rt.write().await;
77	            *w = routes;
78	        });
79	        router
80	    }
81	
82	    /// Reload routes from the live schema catalog.
83	    pub async fn reload(&self) {
84	        let routes = Self::load_routes_from_shm();
85	        let count = routes.len();
86	        let mut w = self.routes.write().await;
87	        *w = routes;
88	        info!(count, "SchemaRouter reloaded plugin routes from SHM");
89	    }
90	
91	    /// List all currently routable plugin IDs.
92	    pub async fn list_plugin_ids(&self) -> Vec<String> {
93	        let r = self.routes.read().await;
94	        r.keys().cloned().collect()
95	    }
96	
97	    /// Get the route for a specific plugin.
98	    pub async fn get_route(&self, plugin_id: &str) -> Option<PluginRoute> {
99	        let r = self.routes.read().await;
100	        r.get(plugin_id).cloned()
101	    }
102	
103	    /// Call a method on a plugin via its schema-derived D-Bus route.
104	    ///
105	    /// This is the core "schema-driven passthrough" — the caller only needs
106	    /// to know the plugin_id and method_name; the router resolves the D-Bus
107	    /// destination, path, and interface automatically.
108	    pub async fn call_method(
109	        &self,
110	        plugin_id: &str,
111	        method_name: &str,
112	        json_args: &str,
113	    ) -> Result<String, SchemaRouterError> {
114	        let route = self
115	            .get_route(plugin_id)
116	            .await
117	            .ok_or_else(|| SchemaRouterError::PluginNotFound(plugin_id.to_string()))?;
118	
119	        // Validate that the method exists in the schema.
120	        if !route.methods.is_empty() && !route.methods.contains_key(method_name) {
121	            return Err(SchemaRouterError::MethodNotFound {
122	                plugin_id: plugin_id.to_string(),
123	                method: method_name.to_string(),
124	            });
125	        }
126	
127	        let conn = self
128	            .dbus_connection
129	            .get()
130	            .ok_or(SchemaRouterError::DbusUnavailable)?;
131	
132	        let proxy = Proxy::new(
133	            conn,
134	            route.dbus_destination.as_str(),
135	            route.dbus_path.as_str(),
136	            route.dbus_interface.as_str(),
137	        )
138	        .await
139	        .map_err(|e| SchemaRouterError::ProxyBuildFailed(e.to_string()))?;
140	
141	        let result: String = proxy
142	            .call(method_name, &(json_args.to_string(),))
143	            .await
144	            .map_err(|e| SchemaRouterError::DbusCallFailed {
145	                method: method_name.to_string(),
146	                error: e.to_string(),
147	            })?;
148	
149	        Ok(result)
150	    }
151	
152	    /// Get a property from a plugin via its schema-derived D-Bus route.
153	    pub async fn get_property(
154	        &self,
155	        plugin_id: &str,
156	        property_name: &str,
157	    ) -> Result<String, SchemaRouterError> {
158	        let route = self
159	            .get_route(plugin_id)
160	            .await
161	            .ok_or_else(|| SchemaRouterError::PluginNotFound(plugin_id.to_string()))?;
162	
163	        let conn = self
164	            .dbus_connection
165	            .get()
166	            .ok_or(SchemaRouterError::DbusUnavailable)?;
167	
168	        let props = zbus::fdo::PropertiesProxy::builder(conn)
169	            .destination(route.dbus_destination.as_str())
170	            .map_err(|e| SchemaRouterError::ProxyBuildFailed(e.to_string()))?
171	            .path(route.dbus_path.as_str())
172	            .map_err(|e| SchemaRouterError::ProxyBuildFailed(e.to_string()))?
173	            .build()
174	            .await
175	            .map_err(|e| SchemaRouterError::ProxyBuildFailed(e.to_string()))?;
176	
177	        let iface = zbus::names::InterfaceName::try_from(route.dbus_interface.as_str())
178	            .map_err(|e| SchemaRouterError::ProxyBuildFailed(e.to_string()))?;
179	
180	        let val: zbus::zvariant::OwnedValue = props
181	            .get(iface, property_name)
182	            .await
183	            .map_err(|e| SchemaRouterError::DbusCallFailed {
184	                method: format!("Get({})", property_name),
185	                error: e.to_string(),
186	            })?;
187	
188	        serde_json::to_string(&val)
189	            .map_err(|e| SchemaRouterError::SerializationFailed(e.to_string()))
190	    }
191	
192	    /// Set a property on a plugin via its schema-derived D-Bus route.
193	    pub async fn set_property(
194	        &self,
195	        plugin_id: &str,
196	        property_name: &str,
197	        json_value: &str,
198	    ) -> Result<(), SchemaRouterError> {
199	        let route = self
200	            .get_route(plugin_id)
201	            .await
202	            .ok_or_else(|| SchemaRouterError::PluginNotFound(plugin_id.to_string()))?;
203	
204	        let conn = self
205	            .dbus_connection
206	            .get()
207	            .ok_or(SchemaRouterError::DbusUnavailable)?;
208	
209	        let props = zbus::fdo::PropertiesProxy::builder(conn)
210	            .destination(route.dbus_destination.as_str())
211	            .map_err(|e| SchemaRouterError::ProxyBuildFailed(e.to_string()))?
212	            .path(route.dbus_path.as_str())
213	            .map_err(|e| SchemaRouterError::ProxyBuildFailed(e.to_string()))?
214	            .build()
215	            .await
216	            .map_err(|e| SchemaRouterError::ProxyBuildFailed(e.to_string()))?;
217	
218	        let iface = zbus::names::InterfaceName::try_from(route.dbus_interface.as_str())
219	            .map_err(|e| SchemaRouterError::ProxyBuildFailed(e.to_string()))?;
220	
221	        let value: serde_json::Value = serde_json::from_str(json_value)
222	            .map_err(|e| SchemaRouterError::SerializationFailed(e.to_string()))?;
223	
224	        // Convert JSON to zvariant Value for D-Bus transport.
225	        let zval = json_to_zvariant_value(&value)?;
226	
227	        props
228	            .set(iface, property_name, zval.into())
229	            .await
230	            .map_err(|e| SchemaRouterError::DbusCallFailed {
231	                method: format!("Set({})", property_name),
232	                error: e.to_string(),
233	            })?;
234	
235	        Ok(())
236	    }
237	
238	    // ── Private helpers ─────────────────────────────────────────────────────
239	
240	    /// Load all plugin routes from the live schema catalog in shared memory.
241	    fn load_routes_from_shm() -> HashMap<String, PluginRoute> {
242	        let Ok(bytes) = std::fs::read(LIVE_SCHEMA_PATH) else {
243	            warn!("SchemaRouter: cannot read {}", LIVE_SCHEMA_PATH);
244	            return HashMap::new();
245	        };
246	        let Ok(root) = serde_json::from_slice::<JsonValue>(&bytes) else {
247	            warn!("SchemaRouter: invalid JSON in {}", LIVE_SCHEMA_PATH);
248	            return HashMap::new();
249	        };
250	        let Some(catalog) = root.as_object() else {
251	            warn!("SchemaRouter: root is not an object in {}", LIVE_SCHEMA_PATH);
252	            return HashMap::new();
253	        };
254	
255	        let mut routes = HashMap::new();
256	
257	        for (plugin_id, entries) in catalog {
258	            let schema = match entries.as_array().and_then(|items| items.first()) {
259	                Some(s) => s,
260	                None => continue,
261	            };
262	
263	            let route = Self::build_route(plugin_id, schema);
264	            debug!(plugin_id, dbus_path = %route.dbus_path, "SchemaRouter: registered route");
265	            routes.insert(plugin_id.clone(), route);
266	        }
267	
268	        info!(
269	            count = routes.len(),
270	            "SchemaRouter: loaded routes from {}",
271	            LIVE_SCHEMA_PATH
272	        );
273	        routes
274	    }
275	
276	    /// Build a PluginRoute from a schema entry.
277	    fn build_route(plugin_id: &str, schema: &JsonValue) -> PluginRoute {
278	        let dbus_path = format!("{}/{}", PLUGIN_BASE_PATH, plugin_id);
279	        let dbus_destination = BASE_SERVICE_NAME.to_string();
280	        let dbus_interface = op_plugins::canonical::plugin_interface(plugin_id);
281	
282	        // Extract methods from schema fields that have "method" type or from
283	        // a dedicated "methods" key.
284	        let methods = Self::extract_methods(schema);
285	        let properties = Self::extract_properties(schema);
286	
287	        PluginRoute {
288	            plugin_id: plugin_id.to_string(),
289	            dbus_path,
290	            dbus_destination,
291	            dbus_interface,
292	            methods,
293	            properties,
294	        }
295	    }
296	
297	    /// Extract method definitions from a schema.
298	    fn extract_methods(schema: &JsonValue) -> HashMap<String, JsonValue> {
299	        let mut methods = HashMap::new();
300	
301	        // Look for a "methods" key in the schema.
302	        if let Some(method_map) = schema.get("methods").and_then(|m| m.as_object()) {
303	            for (name, def) in method_map {
304	                methods.insert(name.clone(), def.clone());
305	            }
306	        }
307	
308	        // Also look in "fields" for entries with type "method".
309	        if let Some(fields) = schema.get("fields").and_then(|f| f.as_array()) {
310	            for field in fields {
311	                let field_type = field.get("field_type").and_then(|t| t.as_str());
312	                if field_type == Some("method") || field_type == Some("Method") {
313	                    if let Some(name) = field.get("name").and_then(|n| n.as_str()) {
314	                        methods.insert(name.to_string(), field.clone());
315	                    }
316	                }
317	            }
318	        }
319	
320	        methods
321	    }
322	
323	    /// Extract property definitions from a schema.
324	    fn extract_properties(schema: &JsonValue) -> HashMap<String, JsonValue> {
325	        let mut properties = HashMap::new();
326	
327	        if let Some(fields) = schema.get("fields").and_then(|f| f.as_array()) {
328	            for field in fields {
329	                let field_type = field.get("field_type").and_then(|t| t.as_str());
330	                // Everything that isn't a method is a property.
331	                if field_type != Some("method") && field_type != Some("Method") {
332	                    if let Some(name) = field.get("name").and_then(|n| n.as_str()) {
333	                        properties.insert(name.to_string(), field.clone());
334	                    }
335	                }
336	            }
337	        }
338	
339	        properties
340	    }
341	}
342	
343	// ── Error type ──────────────────────────────────────────────────────────────
344	
345	#[derive(Debug, thiserror::Error)]
346	pub enum SchemaRouterError {
347	    #[error("plugin not found in schema catalog: {0}")]
348	    PluginNotFound(String),
349	
350	    #[error("method '{method}' not found on plugin '{plugin_id}'")]
351	    MethodNotFound { plugin_id: String, method: String },
352	
353	    #[error("D-Bus system bus unavailable")]
354	    DbusUnavailable,
355	
356	    #[error("failed to build D-Bus proxy: {0}")]
357	    ProxyBuildFailed(String),
358	
359	    #[error("D-Bus call '{method}' failed: {error}")]
360	    DbusCallFailed { method: String, error: String },
361	
362	    #[error("serialization failed: {0}")]
363	    SerializationFailed(String),
364	}
365	
366	impl From<SchemaRouterError> for tonic::Status {
367	    fn from(e: SchemaRouterError) -> Self {
368	        match &e {
369	            SchemaRouterError::PluginNotFound(_) => tonic::Status::not_found(e.to_string()),
370	            SchemaRouterError::MethodNotFound { .. } => {
371	                tonic::Status::unimplemented(e.to_string())
372	            }
373	            SchemaRouterError::DbusUnavailable => tonic::Status::unavailable(e.to_string()),
374	            SchemaRouterError::ProxyBuildFailed(_) => tonic::Status::internal(e.to_string()),
375	            SchemaRouterError::DbusCallFailed { .. } => tonic::Status::internal(e.to_string()),
376	            SchemaRouterError::SerializationFailed(_) => tonic::Status::internal(e.to_string()),
377	        }
378	    }
379	}
380	
381	// ── JSON → zvariant conversion helper ───────────────────────────────────────
382	
383	fn json_to_zvariant_value(
384	    value: &serde_json::Value,
385	) -> Result<zbus::zvariant::Value<'static>, SchemaRouterError> {
386	    use zbus::zvariant::Value as ZValue;
387	    match value {
388	        serde_json::Value::Null => Ok(ZValue::from("")),
389	        serde_json::Value::Bool(b) => Ok(ZValue::from(*b)),
390	        serde_json::Value::Number(n) => {
391	            if let Some(i) = n.as_i64() {
392	                Ok(ZValue::from(i))
393	            } else if let Some(f) = n.as_f64() {
394	                Ok(ZValue::from(f))
395	            } else {
396	                Ok(ZValue::from(0i64))
397	            }
398	        }
399	        serde_json::Value::String(s) => Ok(ZValue::from(s.clone())),
400	        _ => {
401	            // For complex types, serialize to JSON string and pass as string.
402	            let json_str = serde_json::to_string(value)
403	                .map_err(|e| SchemaRouterError::SerializationFailed(e.to_string()))?;
404	            Ok(ZValue::from(json_str))
405	        }
406	    }
407	}
