pub async fn mutate(
    &self,
    plugin_id: String,
    object_path: String,
    change_type: ChangeType,
    member_name: Option<String>,
    value: simd_json::OwnedValue,
    actor_id: String,
    _capability_id: Option<String>,
) -> anyhow::Result<MutationResult> {
    let mut old_value = None;

    // 1. Write to authoritative RCP store
    if plugin_id == "net" || object_path.contains("/ovsdb/") {
        // OVSDB Authoritative Path
        if change_type == ChangeType::MethodCall {
            if let Some(method) = &member_name {
                match method.as_str() {
                    "create_bridge" => {
                        if let Some(name) = value.as_str() {
                            self.ovsdb.create_bridge(name).await?;
                        }
                    }
                    "add_port" => {
                        if let Some(args) = value.as_array() {
                            if args.len() >= 2 {
                                if let (Some(br), Some(port)) =
                                    (args[0].as_str(), args[1].as_str())
                                {
                                    self.ovsdb.add_port(br, port).await?;
                                }
                            }
                        }
                    }
                    _ => {
                        // Fallback to generic D-Bus call if it's a known service
                        let _ = self
                            .call_dbus_method(
                                &format!("org.opdbus.{}.v1", plugin_id),
                                &object_path,
                                "org.opdbus.OvsdbV1",
                                method,
                                vec![value.clone()],
                                &actor_id,
                                &_capability_id,
                            )
                            .await?;
                    }
                }
            }
        } else if change_type == ChangeType::PropertySet {
            if let Some(prop) = &member_name {
                // Extract bridge name from path if possible
                // Path format: /org/opdbus/v1/ovsdb/Bridge/bridge_name
                let parts: Vec<&str> = object_path.split('/').collect();
                if parts.len() >= 6 && parts[4] == "Bridge" {
                    let br_name = parts[5].replace('_', "-");
                    if let Some(val_str) = value.as_str() {
                        self.ovsdb
                            .set_bridge_property(&br_name, prop, val_str)
                            .await?;
                    }
                }
            }
        }
    } else {
        // NonNet / Generic Plugin Path
        if change_type == ChangeType::PropertySet {
            // Get old value for the footprint before update from cache
            old_value = self.get_state(&plugin_id).await.and_then(|v| {
                if let Some(prop) = &member_name {
                    v.get(prop).cloned()
                } else {
                    Some(v)
                }
            });

            // For NonNet plugins, we update the NonNetDb which is authoritative for non-network state
            if let Some(rows) = value.as_array() {
                let rows_vec: Vec<simd_json::OwnedValue> = rows.to_vec();
                self.nonnet.update_table(&plugin_id, rows_vec).await;
            }
        }
    }

    // 2. Record and broadcast change
    let change = self
        .process_authoritative_change(
            plugin_id,
            object_path,
            change_type,
            member_name,
            old_value,
            value.clone(),
            vec![], // Automatically computed in process_authoritative_change
            actor_id,
            ChangeSource::Grpc,
        )
        .await
        .map_err(|e| anyhow::anyhow!(e))?;

    // Write the Identity Sled with the updated mutation index.
    {
        let (existing_pubkey_b64, existing_trace_hex) = if let Ok((ptr, _mmap)) = read_sled() {
            unsafe {
                let sled = &*ptr;
                (
                    base64::engine::general_purpose::STANDARD.encode(sled.wireguard_pubkey),
                    sled.trace_id_hex(),
                )
            }
        } else {
            (String::new(), String::new())
        };
        if let Err(e) =
            write_sled_full(&existing_pubkey_b64, change.event_id, &existing_trace_hex)
        {
            tracing::warn!("sled write after mutation failed: {}", e);
        }
    }

    Ok(MutationResult {
        success: true,
        event_id: change.event_id,
        event_hash: change.event_hash,
        result: Some(value),
        error: None,
    })
}

/// Backward-compatible wrapper for gRPC Mutations.
#[allow(clippy::too_many_arguments)]
pub async fn process_grpc_mutation(
    &self,
    plugin_id: String,
    object_path: String,
    change_type: ChangeType,
    member_name: Option<String>,
    value: simd_json::OwnedValue,
    actor_id: String,
    capability_id: Option<String>,
) -> anyhow::Result<MutationResult> {
    self.mutate(
        plugin_id,
        object_path,
        change_type,
        member_name,
        value,
        actor_id,
        capability_id,
    )
    .await
}

/// Fetch current state for a specific plugin from authoritative cache
pub async fn get_state(&self, plugin_id: &str) -> Option<simd_json::OwnedValue> {
    let cache = self.state_cache.read().await;
    cache.get(plugin_id).cloned()
}

//! Schema-Driven Dynamic gRPC Router
//!
//! Reads the live schema catalog from `/dev/shm/live-schema.json` (combined
//! monolith) and/or per-plugin schema files from the `schemas/plugin/` directory.
//! Dynamically routes incoming gRPC calls to their corresponding D-Bus objects
//! at `/org/opdbus/v1/plugins/<plugin>`.
//!
//! Every plugin defined in the schema catalog is automatically exposed as a
//! gRPC-callable service through the bridge. Unknown methods are rejected by
//! schema validation — no hand-rolling required.
//!
//! ## Schema Access Paths (both supported)
//!
//! 1. **Per-plugin files:** `schemas/plugin/<name>.json` — individual schema objects.
//! 2. **Combined monolith:** `/dev/shm/live-schema.json` — derived catalog of all plugins.
//!
//! The manifest hash is read, never re-computed. Consumers trust the manifest.

use std::collections::HashMap;
use std::path::Path;
use std::sync::Arc;

use serde_json::Value as JsonValue;
use tokio::sync::RwLock;
use tracing::{debug, info};
use zbus::{Connection, Proxy};

use op_plugins::canonical::{self, BASE_SERVICE_NAME};

/// The combined monolith catalog in shared memory.
const LIVE_SCHEMA_PATH: &str = "/dev/shm/live-schema.json";

/// Per-plugin schema directory (relative to project root, resolved at runtime).
const PER_PLUGIN_SCHEMA_DIR: &str = "/etc/opdbus/schemas/plugin";

/// A schema-derived route entry for a plugin.
#[derive(Debug, Clone)]
pub struct PluginRoute {
    /// Plugin identifier (e.g. "unix_socket", "wireguard").
    pub plugin_id: String,
    /// Canonical D-Bus object path: `/org/opdbus/v1/plugins/<plugin_id>`.
    pub dbus_path: String,
    /// Canonical D-Bus destination (bus name): `org.opdbus.v1`.
    pub dbus_destination: String,
    /// Canonical D-Bus interface: `org.opdbus.v1.Plugin.<PluginName>`.
    pub dbus_interface: String,
    /// Methods declared in the schema (name → argument JSON schema).
    pub methods: HashMap<String, JsonValue>,
    /// Properties declared in the schema (name → field schema).
    pub properties: HashMap<String, JsonValue>,
}

/// The dynamic schema router that maps plugin_id → D-Bus route.
pub struct SchemaRouter {
    /// Plugin routes keyed by plugin_id.
    routes: Arc<RwLock<HashMap<String, PluginRoute>>>,
    /// D-Bus system connection (shared with SchemaEngine).
    dbus_connection: Arc<tokio::sync::OnceCell<Connection>>,
}

impl SchemaRouter {
    /// Create a new SchemaRouter and load routes from both schema sources.
    ///
    /// Loads synchronously at startup — the schema in /dev/shm is authoritative
    /// present-state and is always available. No polling or watchers.
    pub fn new(dbus_connection: Arc<tokio::sync::OnceCell<Connection>>) -> Self {
        let routes = Self::load_all_routes();
        info!(
            count = routes.len(),
            "SchemaRouter initialized from schema catalog"
        );
        Self {
            routes: Arc::new(RwLock::new(routes)),
            dbus_connection,
        }
    }

