1	//! D-Bus object server for projections.
2	//!
3	//! Serves every Projection as a D-Bus object under org.opdbus.projection at
4	//! /org/opdbus/v1/plugins/<category>/<id>, e.g. /org/opdbus/v1/plugins/system/memory
5	//! or /org/opdbus/v1/plugins/system/process/1234. Nothing mounts outside the
6	//! plugins root: no plugin means no schema means no object.
7	
8	use anyhow::Result;
9	use std::collections::HashMap;
10	use std::sync::Arc;
11	use tokio::sync::RwLock;
12	use tracing::{debug, info};
13	use zbus::{connection::Builder, interface, object_server::SignalEmitter, Connection};
14	
15	use crate::data_models::Projection;
16	
17	/// A single projected object on the D-Bus object server.
18	pub struct ProjectedObject {
19	    pub entity_type: String,
20	    pub entity_id: String,
21	    /// JSON-serialized projection data
22	    pub data_json: Arc<RwLock<String>>,
23	    pub state: Arc<RwLock<String>>,
24	}
25	
26	#[interface(name = "org.opdbus.projection.v1.Object")]
27	impl ProjectedObject {
28	    /// The schema/entity type for this object (e.g. "system.memory")
29	    #[zbus(property)]
30	    async fn entity_type(&self) -> &str {
31	        &self.entity_type
32	    }
33	
34	    /// The unique entity ID within its type
35	    #[zbus(property)]
36	    async fn entity_id(&self) -> &str {
37	        &self.entity_id
38	    }
39	
40	    /// Current projection state: Valid, Quarantined, Degraded, etc.
41	    #[zbus(property)]
42	    async fn state(&self) -> String {
43	        self.state.read().await.clone()
44	    }
45	
46	    /// Full projection data as a JSON string
47	    #[zbus(property)]
48	    async fn data(&self) -> String {
49	        self.data_json.read().await.clone()
50	    }
51	
52	    /// Signal emitted when this object's data changes
53	    #[zbus(signal)]
54	    async fn updated(emitter: &SignalEmitter<'_>, data_json: &str) -> zbus::Result<()>;
55	}
56	
57	/// Derives the D-Bus object path from a projection's entity_type and entity_id.
58	///
59	/// Every projected object lives under the single plugins root. No plugin means
60	/// no schema means no object — nothing is ever mounted outside this path.
61	///
62	/// entity_type "system.memory"    → /org/opdbus/v1/plugins/system/memory
63	/// entity_type "system.process"   → /org/opdbus/v1/plugins/system/process/<entity_id>
64	/// entity_type "identity.sled"    → /org/opdbus/v1/plugins/identity/sled
65	/// entity_type "ovsdb_bridge"     → /org/opdbus/v1/plugins/ovsdb/bridge/<entity_id>
66	pub fn projection_path(entity_type: &str, entity_id: &str) -> String {
67	    // The ONLY path projections are allowed to mount under.
68	    const PLUGIN_ROOT: &str = "/org/opdbus/v1/plugins";
69	
70	    // Replace dots and underscores in type with slashes for the path prefix
71	    let type_path = entity_type.replace(['.', '_'], "/").to_lowercase();
72	
73	    // For singleton objects (memory, cpu, filesystems, network) the entity_id
74	    // is typically the same as the type — omit it to avoid redundancy.
75	    let is_singleton = entity_id == entity_type
76	        || entity_id.is_empty()
77	        || entity_id == "memory"
78	        || entity_id == "cpu"
79	        || entity_id == "filesystems"
80	        || entity_id == "network"
81	        || entity_id == "sled";
82	
83	    if is_singleton {
84	        format!("{}/{}", PLUGIN_ROOT, type_path)
85	    } else {
86	        // Sanitize entity_id for use in a path segment
87	        let safe_id: String = entity_id
