45	pub struct UnixSocketPlugin {
46	    /// Live listeners keyed by socket path. Holding the `UnixListener` keeps the
47	    /// socket bound for the lifetime of the plugin; dropping it tears it down.
48	    active: Arc<Mutex<HashMap<String, UnixListener>>>,
49	}
