51	impl UnixSocketPlugin {
52	    pub fn new() -> Self {
53	        Self {
54	            active: Arc::new(Mutex::new(HashMap::new())),
55	        }
56	    }
57	
58	    /// Read this plugin's desired socket set straight from the single active
59	    /// schema catalog in shared memory (zero-copy 1:1). The catalog is keyed by
60	    /// plugin name and each entry carries the schema-declared state.
61	    fn read_desired() -> UnixSocketState {
62	        let Ok(mut bytes) = std::fs::read(SHM_SCHEMA_PATH) else {
63	            return UnixSocketState::default();
64	        };
65	        let Ok(catalog) = simd_json::to_owned_value(&mut bytes) else {
66	            return UnixSocketState::default();
67	        };
68	        let Some(state) = catalog
69	            .get("unix_socket")
70	            .and_then(|versions| versions.as_array())
71	            .and_then(|versions| versions.last())
72	            .and_then(|schema| schema.get("example"))
73	        else {
74	            return UnixSocketState::default();
75	        };
76	        simd_json::serde::from_owned_value::<UnixSocketState>(state.clone()).unwrap_or_default()
77	    }
78	
79	    /// Bind a single endpoint, replacing any stale socket file. Returns `true`
80	    /// when a new listener was created.
81	    fn ensure_bound(
82	        active: &mut HashMap<String, UnixListener>,
83	        endpoint: &SocketEndpoint,
84	    ) -> Result<bool> {
85	        if active.contains_key(&endpoint.path) {
86	            return Ok(false);
87	        }
88	        if let Some(parent) = Path::new(&endpoint.path).parent() {
89	            std::fs::create_dir_all(parent)?;
90	        }
91	        if Path::new(&endpoint.path).exists() {
92	            std::fs::remove_file(&endpoint.path)?;
93	        }
94	        let listener = UnixListener::bind(&endpoint.path)?;
95	        listener.set_nonblocking(true)?;
96	        active.insert(endpoint.path.clone(), listener);
97	        info!(
98	            socket = %endpoint.path,
99	            port = endpoint.port,
100	            protocol = %endpoint.protocol,
101	            "bound unix socket endpoint"
102	        );
103	        Ok(true)
104	    }
105	
106	    /// Drop a listener and unlink its socket file. Returns `true` when removed.
107	    fn unbind(active: &mut HashMap<String, UnixListener>, path: &str) -> bool {
108	        if active.remove(path).is_some() {
109	            if let Err(error) = std::fs::remove_file(path) {
110	                warn!(socket = %path, %error, "failed to unlink unix socket file");
111	            }
112	            true
113	        } else {
114	            false
115	        }
116	    }
117	
118	    /// Reconcile the live listeners to exactly the supplied desired set.
119	    fn reconcile(&self, desired: &UnixSocketState) -> ApplyResult {
120	        let mut active = self.active.lock();
121	        let mut changes_applied = Vec::new();
122	        let mut errors = Vec::new();
123	
124	        let wanted: HashSet<String> = desired.sockets.iter().map(|s| s.path.clone()).collect();
125	
126	        for endpoint in &desired.sockets {
127	            match Self::ensure_bound(&mut active, endpoint) {
128	                Ok(true) => changes_applied.push(format!(
129	                    "created socket {} (port {}, {})",
130	                    endpoint.path, endpoint.port, endpoint.protocol
131	                )),
132	                Ok(false) => {}
133	                Err(error) => errors.push(format!(
134	                    "failed to create socket {}: {}",
135	                    endpoint.path, error
136	                )),
137	            }
138	        }
139	
140	        let stale: Vec<String> = active
141	            .keys()
142	            .filter(|path| !wanted.contains(*path))
143	            .cloned()
144	            .collect();
145	        for path in stale {
146	            if Self::unbind(&mut active, &path) {
147	                changes_applied.push(format!("removed socket {}", path));
148	            }
149	        }
150	
151	        ApplyResult {
152	            success: errors.is_empty(),
153	            changes_applied,
154	            errors,
155	            checkpoint: None,
156	        }
157	    }
158	}
