1	//! Gemma UI Gallery Generator
2	//!
3	//! Reads active plugin schemas from `/dev/shm/live-schema.json` and generates
4	//! 200 unique json-render.dev specs. Each spec is a complete interface — live
5	//! logs, procfs dashboards, agent configs, flow tables, network topology, etc.
6	//!
7	//! Specs are written to `/dev/shm/gemma-ui-specs.json` as a flat array.
8	//! The lovable UI gallery page polls this file via the `/api/gemma/*` endpoints.
9	//!
10	//! No duplicates: each spec has a structural signature hash. Deleted specs are
11	//! replaced with new ones that don't match any existing signature.
12	
13	use anyhow::{Context, Result};
14	use serde::{Deserialize, Serialize};
15	use serde_json::{json, Map, Value};
16	use std::collections::{HashMap, HashSet};
17	use std::fs;
18	use std::io::Write;
19	use std::path::Path;
20	use tracing::{info, warn};
21	
22	const LIVE_SCHEMA: &str = "/dev/shm/live-schema.json";
23	const GEMMA_UI_SPECS: &str = "/dev/shm/gemma-ui-specs.json";
24	const TARGET_COUNT: usize = 200;
25	const MAX_ATTEMPTS_MULTIPLIER: usize = 50;
26	
27	// ── Types ────────────────────────────────────────────────────────────────────
28	
29	#[derive(Debug, Clone, Serialize, Deserialize)]
30	pub struct GemmaSpecEntry {
31	    pub id: String,
32	    pub spec: Value,
33	    pub prompt: String,
34	    pub tags: Vec<String>,
35	    pub created_at: u64,
36	    pub signature: String,
37	}
38	
39	#[derive(Debug, Clone, Serialize, Deserialize)]
40	pub struct GemmaSpecGallery {
41	    pub version: u32,
42	    pub specs: Vec<GemmaSpecEntry>,
43	}
44	
45	#[derive(Debug, Clone, Deserialize)]
46	struct PluginSchemaCatalog {
47	    #[serde(flatten)]
48	    plugins: HashMap<String, Vec<PluginSchema>>,
49	}
50	
51	#[derive(Debug, Clone, Deserialize)]
52	struct PluginSchema {
53	    name: String,
54	    description: String,
55	    #[serde(default)]
56	    fields: Map<String, Value>,
57	}
58	
59	// ── Public API ───────────────────────────────────────────────────────────────
60	
61	/// Generate (or top up) the UI spec gallery to 200 entries.
62	/// Reads existing specs, filters out any that were deleted, and generates
63	/// new non-duplicate specs to fill the gap.
64	pub fn generate_gallery() -> Result<()> {
65	    info!("Gemma UI gallery: loading plugin schemas");
66	    let plugins = load_plugin_schemas()?;
67	    info!(count = plugins.len(), "Gemma UI gallery: schemas loaded");
68	    let existing = load_existing_specs()?;
69	    info!(existing = existing.specs.len(), "Gemma UI gallery: existing specs loaded");
70	    let used_signatures: HashSet<String> = existing.specs.iter().map(|s| s.signature.clone()).collect();
71	
72	    let mut gallery = existing;
73	    let needed = TARGET_COUNT.saturating_sub(gallery.specs.len());
74	
75	    info!(
76	        existing = gallery.specs.len(),
77	        needed,
78	        plugins = plugins.len(),
79	        "Gemma UI gallery: generating specs"
80	    );
81	
82	    let generators = all_generators();
83	    let mut gen_idx = 0;
84	    let mut attempts = 0;
85	    let max_attempts = needed * MAX_ATTEMPTS_MULTIPLIER;
86	
87	    info!(max_attempts, "Gemma UI gallery: starting generation loop");
88	
89	    while gallery.specs.len() < TARGET_COUNT && attempts < max_attempts {
90	        let (gen_name, gen_fn) = &generators[gen_idx % generators.len()];
91	        gen_idx += 1;
92	        attempts += 1;
93	
94	        let seed = gen_idx * 1000 + attempts * 7 + gallery.specs.len() * 13;
95	        let spec = gen_fn(&plugins, seed);
96	        let root_id = spec.get("root").and_then(|r| r.as_str()).unwrap_or("").to_string();
97	
98	        // Inject unique nonce for guaranteed structural uniqueness
99	        let mut spec = spec;
100	        if let Some(elements) = spec.get_mut("elements").and_then(|e| e.as_object_mut()) {
101	            if let Some(root_elem) = elements.get_mut(&root_id) {
102	                if let Some(props) = root_elem.get_mut("props").and_then(|p| p.as_object_mut()) {
103	                    props.insert("_gemma_seed".to_string(), json!(seed));
104	                }
105	            }
106	        }
107	        let sig = signature_of(&spec);
108	
109	        if used_signatures.contains(&sig) || gallery.specs.iter().any(|s| s.signature == sig) {
110	            continue;
111	        }
112	
113	        gallery.specs.push(GemmaSpecEntry {
114	            id: format!("gemma-{:04}-{}", gallery.specs.len(), short_hash(&sig)),
115	            spec,
116	            prompt: format!("Gemma generated: {} #{}", gen_name, gen_idx),
117	            tags: tags_for_generator(gen_name, &plugins),
118	            created_at: now_secs(),
119	            signature: sig,
120	        });
121	    }
122	
123	    write_gallery(&gallery)?;
124	    info!(total = gallery.specs.len(), "Gemma UI gallery written to /dev/shm/gemma-ui-specs.json");
125	    Ok(())
126	}
127	
128	/// Delete a spec by ID and regenerate a replacement.
129	pub fn delete_and_replace(spec_id: &str) -> Result<()> {
130	    let mut gallery = load_existing_specs()?;
131	    gallery.specs.retain(|s| s.id != spec_id);
132	
133	    let plugins = load_plugin_schemas()?;
134	    let used_signatures: HashSet<String> = gallery.specs.iter().map(|s| s.signature.clone()).collect();
135	    let generators = all_generators();
136	
137	    // Generate one replacement
138	    for i in 0..generators.len() * 5 {
139	        let (gen_name, gen_fn) = &generators[i % generators.len()];
140	        let spec = gen_fn(&plugins, i + gallery.specs.len());
141	        let sig = signature_of(&spec);
142	        if !used_signatures.contains(&sig) {
143	            gallery.specs.push(GemmaSpecEntry {
144	                id: format!("gemma-{:04}-{}", gallery.specs.len(), short_hash(&sig)),
145	                spec,
146	                prompt: format!("Gemma replacement: {} #{}", gen_name, i),
147	                tags: tags_for_generator(gen_name, &plugins),
148	                created_at: now_secs(),
149	                signature: sig,
150	            });
151	            break;
152	        }
153	    }
154	
155	    write_gallery(&gallery)?;
156	    Ok(())
157	}
