208	// ── Helper: build a flat-tree spec ───────────────────────────────────────────
209	
210	fn spec(root: &str, elements: Vec<(&str, Value, Vec<&str>)>) -> Value {
211	    let mut map = Map::new();
212	    for (id, element, children) in &elements {
213	        let mut elem = element.clone();
214	            if let Some(obj) = elem.as_object_mut() {
215	                if !children.is_empty() {
216	                    obj.insert("children".to_string(), json!(children.iter().map(|c| *c).collect::<Vec<_>>()));
217	                } else {
218	                    obj.insert("children".to_string(), json!([]));
219	                }
220	            }
221	        map.insert(id.to_string(), elem);
222	    }
223	    json!({
224	        "root": root,
225	        "elements": map,
226	    })
227	}
228	
229	fn el(type_name: &str, props: Value) -> Value {
230	    json!({
231	        "type": type_name,
232	        "props": props,
233	    })
234	}
