377	fn gen_plugin_state(plugins: &HashMap<String, Vec<PluginSchema>>, n: usize) -> Value {
378	    let plugin_names: Vec<&String> = plugins.keys().collect();
379	    if plugin_names.is_empty() {
380	        return gen_live_logs(plugins, n);
381	    }
382	    let plugin_name = plugin_names[n % plugin_names.len()];
383	    let schema = &plugins[plugin_name][0];
384	    let field_count = schema.fields.len();
385	
386	    let field_elements: Vec<Value> = schema.fields.iter().take(8).enumerate().map(|(i, (fname, fval))| {
387	        let ft = fval.get("field_type").and_then(|v| v.as_str()).unwrap_or("string");
388	        let desc = fval.get("description").and_then(|v| v.as_str()).unwrap_or("");
389	        let ro = fval.get("read_only").and_then(|v| v.as_bool()).unwrap_or(false);
390	        let req = fval.get("required").and_then(|v| v.as_bool()).unwrap_or(false);
391	        let ft_str = if ft == "any" { "string" } else if ft.starts_with('{') { "object" } else { ft };
392	        json!({
393	            "name": fname,
394	            "fieldType": ft_str,
395	            "description": desc,
396	            "value": null,
397	            "readOnly": ro,
398	            "required": req,
399	            "enumValues": null,
400	        })
401	    }).collect();
402	
403	    // Build children IDs
404	    let children: Vec<String> = (0..field_elements.len()).map(|i| format!("sf-{i}")).collect();
405	    let child_refs: Vec<&str> = children.iter().map(|s| s.as_str()).collect();
406	
407	    let mut elements: Vec<(&str, Value, Vec<&str>)> = Vec::new();
408	    elements.push((
409	        "card-1",
410	        el("PluginStateCard", json!({
411	            "pluginId": plugin_name,
412	            "title": plugin_name,
413	            "fieldCount": field_count,
414	            "category": schema.description.as_str(),
415	        })),
416	        {
417	            let mut c = child_refs.clone();
418	            c.extend_from_slice(&["btn-row"]);
419	            c
420	        },
421	    ));
422	    for (i, fe) in field_elements.iter().enumerate() {
423	        elements.push((leak(format!("sf-{i}")), el("SchemaField", fe.clone()), vec![]));
424	    }
425	    elements.push((
426	        "btn-row",
427	        el("ButtonGroup", json!({"buttons": [
428	            {"label": "Save", "variant": "default"},
429	            {"label": "Refresh", "variant": "outline"},
430	        ], "selected": 0})),
431	        vec![],
432	    ));
433	
434	    spec("card-1", elements)
435	}
