994	fn signature_of(spec: &Value) -> String {
995	    // Structural signature: component types in traversal order + props shape
996	    let mut sig = String::new();
997	    if let Some(elements) = spec.get("elements").and_then(|e| e.as_object()) {
998	        let root = spec.get("root").and_then(|r| r.as_str()).unwrap_or("");
999	        fn walk(id: &str, elements: &Map<String, Value>, sig: &mut String, depth: usize) {
1000	            if let Some(elem) = elements.get(id) {
1001	                let ty = elem.get("type").and_then(|t| t.as_str()).unwrap_or("?");
1002	                let props = elem.get("props").map(|p| p.to_string()).unwrap_or_default();
1003	                let props_hash = short_hash(&props);
1004	                sig.push_str(&format!("{}:{}:{}|", depth, ty, &props_hash[..8.min(props_hash.len())]));
1005	                if let Some(children) = elem.get("children").and_then(|c| c.as_array()) {
1006	                    for child in children {
1007	                        if let Some(cid) = child.as_str() {
1008	                            walk(cid, elements, sig, depth + 1);
1009	                        }
1010	                    }
1011	                }
1012	            }
1013	        }
1014	        walk(root, elements, &mut sig, 0);
1015	    }
1016	    short_hash(&sig)
1017	}
1018	
1019	fn short_hash(s: &str) -> String {
1020	    use std::collections::hash_map::DefaultHasher;
1021	    use std::hash::{Hash, Hasher};
1022	    let mut hasher = DefaultHasher::new();
1023	    s.hash(&mut hasher);
1024	    format!("{:016x}", hasher.finish())
1025	}
