1031	    if !plugin_names.is_empty() {
1032	        let idx = (gen_name.len() + tags.len()) % plugin_names.len();
1033	        tags.push(plugin_names[idx].clone());
1034	    }
1035	    tags
1036	}
1037	
1038	fn now_secs() -> u64 {
1039	    std::time::SystemTime::now()
1040	        .duration_since(std::time::UNIX_EPOCH)
1041	        .map(|d| d.as_secs())
1042	        .unwrap_or(0)
1043	}
