fn gen_plugin_state(plugins: &HashMap<String, Vec<PluginSchema>>, n: usize) -> Value {
    let plugin_names: Vec<&String> = plugins.keys().collect();
    if plugin_names.is_empty() {
        return gen_live_logs(plugins, n);
    }
    let plugin_name = plugin_names[n % plugin_names.len()];
    let schema = &plugins[plugin_name][0];
    let field_count = schema.fields.len();

    let field_elements: Vec<Value> = schema.fields.iter().take(8).enumerate().map(|(i, (fname, fval))| {
        let ft = fval.get("field_type").and_then(|v| v.as_str()).unwrap_or("string");
        let desc = fval.get("description").and_then(|v| v.as_str()).unwrap_or("");
        let ro = fval.get("read_only").and_then(|v| v.as_bool()).unwrap_or(false);
        let req = fval.get("required").and_then(|v| v.as_bool()).unwrap_or(false);
        let ft_str = if ft == "any" { "string" } else if ft.starts_with('{') { "object" } else { ft };
        json!({
            "name": fname,
            "fieldType": ft_str,
            "description": desc,
            "value": null,
            "readOnly": ro,
            "required": req,
            "enumValues": null,
        })
    }).collect();

    // Build children IDs
    let children: Vec<String> = (0..field_elements.len()).map(|i| format!("sf-{i}")).collect();
    let child_refs: Vec<&str> = children.iter().map(|s| s.as_str()).collect();

    let mut elements: Vec<(&str, Value, Vec<&str>)> = Vec::new();
    elements.push((
        "card-1",
        el("PluginStateCard", json!({
            "pluginId": plugin_name,
            "title": plugin_name,
            "fieldCount": field_count,
            "category": schema.description.as_str(),
        })),
        {
            let mut c = child_refs.clone();
            c.extend_from_slice(&["btn-row"]);
            c
        },
    ));
    for (i, fe) in field_elements.iter().enumerate() {
        elements.push((leak(format!("sf-{i}")), el("SchemaField", fe.clone()), vec![]));
    }
    elements.push((
        "btn-row",
        el("ButtonGroup", json!({"buttons": [
            {"label": "Save", "variant": "default"},
            {"label": "Refresh", "variant": "outline"},
        ], "selected": 0})),
        vec![],
    ));

    spec("card-1", elements)
}

