1	//! json-render.dev DSL → egui interpreter.
2	//!
3	//! This is the **only** code path allowed to draw widgets in the operator
4	//! console. Every view binds via [`render`] with a `PinnedRef` resolved from
5	//! the live [`CatalogSnapshot`]. Unknown ids, missing versions, or unknown
6	//! DSL nodes surface as [`RenderError`] — no silent fallbacks, no raw JSON.
7	//!
8	//! The seed primitive set below is the minimum needed for gemma_brain to
9	//! generate against. Adding a new primitive is a deliberate act: append a
10	//! match arm here and document the DSL key in the json-render.dev catalog
11	//! contract. Never extend by accepting unknown node shapes.
12	
13	use egui::{RichText, Ui};
14	use serde_json::Value;
15	use thiserror::Error as ThisError;
16	
17	use super::dsl::PinnedRef;
18	use super::store::CatalogSnapshot;
19	use crate::theme::*;
20	
21	#[derive(Debug, ThisError)]
22	pub enum RenderError {
23	    #[error("catalog element {id}@{version} not found")]
24	    UnknownElement { id: String, version: u32 },
25	    #[error("catalog spec missing or malformed `kind` field")]
26	    MalformedSpec,
27	    #[error("unknown DSL node kind `{0}` — not in json-render.dev catalog")]
28	    UnknownKind(String),
29	    #[error("schema/value mismatch for element {0}")]
30	    SchemaMismatch(String),
31	}
32	
33	/// Render a bound element. `value` is the live JSON payload (typically from
34	/// `grpc::decode_to_json`); `snapshot` is the current `CatalogStore` view.
35	pub fn render(
36	    ui: &mut Ui,
37	    snapshot: &CatalogSnapshot,
38	    pin: &PinnedRef,
39	    value: &Value,
40	) -> Result<(), RenderError> {
41	    let element = snapshot.resolve(pin).ok_or_else(|| RenderError::UnknownElement {
42	        id: pin.id.clone(),
43	        version: pin.version,
44	    })?;
45	    walk(ui, &element.spec, value)
46	}
47	
48	fn walk(ui: &mut Ui, spec: &Value, value: &Value) -> Result<(), RenderError> {
49	    let kind = spec.get("kind").and_then(Value::as_str).ok_or(RenderError::MalformedSpec)?;
50	    match kind {
51	        // ---------- layout primitives ----------
52	        "stack" => {
53	            let dir = spec.get("dir").and_then(Value::as_str).unwrap_or("v");
54	            let children = spec.get("children").and_then(Value::as_array).cloned().unwrap_or_default();
55	            let render_children = |ui: &mut Ui| -> Result<(), RenderError> {
56	                for child in &children { walk(ui, child, value)?; }
57	                Ok(())
58	            };
59	            let mut out = Ok(());
60	            if dir == "h" {
61	                ui.horizontal(|ui| out = render_children(ui));
62	            } else {
63	                ui.vertical(|ui| out = render_children(ui));
64	            }
65	            out
66	        }
67	
68	        // ---------- text ----------
69	        "label" => {
70	            let bind = spec.get("bind").and_then(Value::as_str);
71	            let text = match bind {
72	                Some(path) => json_pointer(value, path)
73	                    .and_then(|v| v.as_str().map(|s| s.to_string()))
74	                    .unwrap_or_default(),
75	                None => spec.get("text").and_then(Value::as_str).unwrap_or("").to_string(),
